  function rejectOfficerRole(id) {
    var o = officerById(id);
    if (!o) return null;
    if (!isTotalManager()) { toast('직책 승인·반려는 마스터만 할 수 있습니다.', true); return null; }
    o.status = 'revoked';
    o.at = nowStamp();
    o.by = accessDisplay().label;
    audit('권한', '직원 가입 신청 반려 — ' + o.name + ' (' + officerRoleMeta(o.role).label + ')');
    save(); renderAdminRoleBar(); renderOfficerPanel();
    toast(o.name + ' 님의 가입 신청을 반려했습니다.');
    return o;
  }
  function officerById(id) {
    var hit = null;
    officerList().forEach(function (o) { if (o.id === id) hit = o; });
    return hit;
  }
  function nextOfficerId() {
    var n = 1;
    officerList().forEach(function (o) {
      var x = Number(String(o.id || '').replace(/[^0-9]/g, ''));
      if (x >= n) n = x + 1;
    });
    return 'OF-' + pad2(n);
  }
  function addOfficer(v) {
    v = v || {};
    var name = String(v.name || '').trim();
    if (!name) { toast('성명을 입력해 주세요.', true); return null; }
    var meta = officerRoleMeta(v.role);
    if (meta.k === 'super') { toast('마스터는 직책자 명단에 등록하지 않습니다.', true); return null; }
    var rec = { id: nextOfficerId(), role: meta.k, name: name,
      company: String(v.company || '').trim(), memberId: v.memberId || '',
      status: 'pending', at: nowStamp(), by: accessDisplay().label };
    officerList().push(rec);
    audit('권한', '직책자 등록 — ' + meta.label + ' ' + name + (rec.company ? ' (' + rec.company + ')' : '') + ' · 승인 대기');
    save(); renderAdminRoleBar(); renderOfficerPanel();
    toast(meta.label + ' ' + name + ' 님을 승인 대기로 등록했습니다. [승인]을 누르면 결재 권한이 생깁니다.');
    return rec;
  }
  function approveOfficerRole(id, role) {
    var o = officerById(id);
    if (!o) return null;
    if (!isTotalManager()) { toast('직책 승인은 마스터만 할 수 있습니다.', true); return null; }
    if (role) {
      o.permRole = role;                                  /* 매트릭스 열(사무실무원1/2 등) */
      o.role = officerRoleKeyOf(role);                    /* 실제 임원 직책 키 */
    }
    o.status = 'approved';
    o.at = nowStamp();
    o.by = accessDisplay().label;
    audit('권한', '직책 승인 — ' + officerRoleMeta(o.role).label + ' ' + o.name + ' (' + accessDisplay().label + ' 승인)');
    save(); renderAdminRoleBar(); renderOfficerPanel(); renderOfficialAll();
    toast(o.name + ' 님(' + officerRoleMeta(o.role).label + ')의 결재 권한을 승인했습니다.');
    return o;
  }
  function revokeOfficerRole(id) {
    var o = officerById(id);
    if (!o) return null;
    o.status = 'revoked';
    o.at = nowStamp();
    o.by = accessDisplay().label;
    if (currentAccessRole() === o.role) ui.adminRole = 'super';
    audit('권한', '직책 권한 회수 — ' + officerRoleMeta(o.role).label + ' ' + o.name + ' (' + accessDisplay().label + ' 처리)');
    save(); renderAdminRoleBar(); renderOfficerPanel(); renderOfficialAll();
    toast(o.name + ' 님(' + officerRoleMeta(o.role).label + ')의 결재 권한을 회수했습니다.');
    return o;
  }
  function removeOfficer(id) {
    var o = officerById(id);
    if (!o) return null;
    db.officers = officerList().filter(function (x) { return x.id !== id; });
    if (currentAccessRole() === o.role) ui.adminRole = 'super';
    audit('권한', '직책자 삭제 — ' + officerRoleMeta(o.role).label + ' ' + o.name);
    save(); renderAdminRoleBar(); renderOfficerPanel();
    toast(o.name + ' 님을 직책자 명단에서 삭제했습니다.');
    return true;
  }

