    var barCls = pct >= 100 ? 'full' : (pct >= 80 ? 'warn' : '');
    /* 이번 주 추첨에 이 게시대로 접수된 건수 — 현황 카드의 `N건 접수중` */
    var reqN = weekRequestCount(p.id);
    var reqPct = (!off && p.cap) ? Math.min(100, Math.round((reqN / p.cap) * 100)) : 0;
    var reqCls = reqN >= p.cap ? 'full' : (reqPct >= 80 ? 'warn' : '');
    var ranks = (mode === 'pick') ? pickedIn(p.id) : [];
    var picked = ranks.length > 0;
