  function printPhotoProof() {
    var rule = $('#printPageRule');
    if (rule) rule.textContent = '@page{size:A4 portrait;margin:8mm}';
    if (document.body && document.body.classList) document.body.classList.add('print-photo');
    try { window.print(); } catch (e) { /* 인쇄 불가 환경 */ }
    setTimeout(function () {
      if (document.body && document.body.classList) document.body.classList.remove('print-photo');
      if (rule) rule.textContent = '';
    }, 600);
  }
  /* 사진 카드 — 관리자(미리보기·삭제) / 접수자(다운로드·인쇄) */
  function photoCardHTML(ph, mode, a) {
    var p = boardById(ph.pid);
    var cell = (p ? p.name : '게시대') + ' ' + photoDongLabel(ph.pid, ph.dong);
    var apps = photoAppsOfCell(ph.week, ph.pid, ph.dong);
    var btns = (mode === 'admin')
      ? '<button class="btn sm ghost" type="button" data-photoview="' + esc(ph.id) + '">🔍 미리보기</button>' +
        '<button class="btn sm danger" type="button" data-photodel="' + esc(ph.id) + '">🗑 삭제</button>'
      : '<button class="btn sm primary" type="button" data-photodl="' + esc(ph.id) + '" data-photofor="' + esc(a ? a.id : '') + '">📥 사진 다운로드</button>' +
        '<button class="btn sm" type="button" data-photoproof="' + esc(a ? a.id : '') + '" data-phid="' + esc(ph.id) + '">🖨️ 인쇄</button>';
    return '<div class="photo-card' + (ph.sample ? ' sample' : '') + '">' +
      '<div class="pc-img" data-photoview="' + esc(ph.id) + '" role="button" tabindex="0" title="클릭하면 확대 보기"><img src="' + photoDataOf(ph) + '" alt="' + esc(cell) + ' 게첨사진" loading="lazy"></div>' +
      '<div class="pc-meta"><b>' + esc(cell) + '</b>' +
        '<span>' + esc(ph.at || '') + ' · ' + esc(ph.by || '') + '</span>' +
        '<span style="font-weight:700;color:var(--navy3)">' + esc(periodTxt(ph.week)) + '</span>' +
        '<span style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">' + photoRetainBadgeHTML(ph) +
          '<span class="sm">보관 만료 ' + esc(photoExpireISO(ph) || '—') + ' (등록일로부터 3개월)</span></span>' +
        '<span>접수 ' + apps.length + '건 연결</span></div>' +
      '<div class="pc-btns">' + btns + '</div></div>';
  }
  /* 접수자 마이페이지 — 접수번호 기준으로 배정 게시대·동 사진 자동 표시 */
  function photoSectionHTML(a) {
    var list = photosForApp(a);
    var retainNote = '<div class="callout info" id="mpPhotoRetain" style="margin-top:12px">' + IC.info +
      '<div><b>게첨사진 보관기간 안내</b> — 게첨 완료 사진은 <b>등록일로부터 3개월(90일)간 보관 후 자동 삭제</b>됩니다. ' +
      '증빙이 필요한 경우 기간 내에 미리 다운로드하거나 인쇄해 보관해 주세요.</div></div>';
    if (!list.length) {
      return '<div class="callout info" id="mpPhotoBox" style="margin-top:14px">' + IC.info +
        '<div><b>📸 게첨사진 등록 대기중</b> — 현장 게첨 후 실무자가 게시대 동 단위로 사진을 등록하면, 이 접수번호에 배정된 게시대·동의 사진이 여기에 자동으로 표시됩니다(등록되면 사진 내려받기·게첨 확인서 인쇄).</div></div>' + retainNote;
    }
    return '<div class="panel" id="mpPhotoBox" style="margin-top:14px">' +
      '<div class="panel-head"><h3>' + IC.doc + ' 📸 게첨사진 · 게첨 확인</h3>' +
      '<span class="sub">' + list.length + '장 · 배정 게시대·동 사진 자동 연결 · 보관 3개월</span></div>' +
      '<div class="photo-grid">' + list.map(function (ph) { return photoCardHTML(ph, 'owner', a); }).join('') + '</div>' +
      '<div class="off-actions" style="margin-top:10px">' +
        '<button class="btn primary" type="button" data-photoproof="' + esc(a.id) + '">🖨️ 게첨 확인서(사진) 전체 인쇄 (' + list.length + '장)</button>' +
        '<span class="hint-txt" style="margin:0">사진마다 A4 1장 · 접수번호·광고주·문구·게시대/동·게첨기간이 함께 인쇄됩니다.</span>' +
      '</div>' + retainNote + '</div>';
  }
  /* 관리자 — 게시대 동 단위 등록 화면 */
  function renderPhotoPanel() {
    if (!has('photoList')) return;
    if (!ui.photoWeek) ui.photoWeek = addDays(currentPostingWeek(), -7);
    var wk = weekStartOf(ui.photoWeek), base = currentPostingWeek();
    if ($('#photoDatePick')) $('#photoDatePick').value = wk;
    var wsel = $('#photoWeek');
    if (wsel) {
      var wopts = [];
      for (var i = -4; i <= 1; i++) wopts.push(addDays(base, i * 7));
      if (wopts.indexOf(wk) < 0) wopts.push(wk);
      wsel.innerHTML = wopts.sort().reverse().map(function (s) {
        var tag = s === base ? ' · 이번 회차(추첨 전)' : (s === addDays(base, -7) ? ' · 이번 주 게첨' : ' · 다른 주');
        return '<option value="' + s + '"' + (s === wk ? ' selected' : '') + '>' + weekRangeTxt(s) + tag + '</option>';
      }).join('');
    }
    var cnt = {};
    db.apps.forEach(function (a) {
      if (weekStartOf(a.start || ROUND.postStart) !== wk) return;
      if (['반려', '미입고취소', '미입금취소', '본인취소', '접수취소', '낙첨'].indexOf(a.status) >= 0) return;
      awardedPlacesOf(a).forEach(function (x) { cnt[x.pid] = (cnt[x.pid] || 0) + (x.qty || 1); });
    });
    var pids = Object.keys(cnt).sort(function (a, b) {
      /* 주요 게시대(의료원·동문동·석지제·중앙고…)를 먼저 — 사무실에서 사진 올릴 때 찾기 쉽게 */
      /* 실제 현장 사진 폴더 순서를 우선 (2026-11-23 김재봉 님 첨부 6장 기준) */
      var fa = folderIndexOf(a, ''), fb = folderIndexOf(b, '');
      if (fa !== fb) return fa - fb;
      var ma = photoIsMajor((boardById(a) || {}).name) ? 0 : 1, mb = photoIsMajor((boardById(b) || {}).name) ? 0 : 1;
      return (ma - mb) || (cnt[b] - cnt[a]) || String(a).localeCompare(String(b));
    });
    if (!pids.length) pids = db.placements.slice(0, 24).map(function (p) { return p.id; });
    if (!ui.photoPid || pids.indexOf(ui.photoPid) < 0) {
      /* 기본 선택 — 그 주차에 사진이 이미 있는 게시대를 먼저 보여 준다 */
      var withPhoto = pids.filter(function (id) { return photoStore().some(function (ph) { return weekStartOf(ph.week) === wk && String(ph.pid) === String(id); }); });
      ui.photoPid = (withPhoto[0] || pids[0]) || '';
      ui.photoDong = '';
    }
    var psel = $('#photoPid');
    if (psel) {
      psel.innerHTML = pids.map(function (id) {
        var p = boardById(id);
        return '<option value="' + esc(id) + '"' + (id === ui.photoPid ? ' selected' : '') + '>' +
          esc(p ? p.name : id) + (cnt[id] ? ' · 배정 ' + cnt[id] + '매' : '') + '</option>';
      }).join('');
    }
    var p = boardById(ui.photoPid);
    var letters = p ? boardLettersOf(p) : [''];
    if (letters.indexOf(ui.photoDong) < 0) ui.photoDong = letters[0];
    var dsel = $('#photoDong');
    if (dsel) {
      letters = letters.slice().sort(function (x, y) { return folderIndexOf(ui.photoPid, x) - folderIndexOf(ui.photoPid, y); });
      dsel.innerHTML = letters.map(function (L) {
        var m = photoAppsOfCell(wk, ui.photoPid, L).length;
        return '<option value="' + esc(L) + '"' + (L === ui.photoDong ? ' selected' : '') + '>' +
          esc(photoDongLabel(ui.photoPid, L)) + ' · ' + esc(photoFolderName({ pid: ui.photoPid, dong: L }).replace(/^_/, '')) +
          (m ? ' · 접수 ' + m + '건' : '') + '</option>';
      }).join('');
    }
    var awardApps = photoAppsOfCell(wk, ui.photoPid, ui.photoDong);
    var cells = photosOfCell(wk, ui.photoPid, ui.photoDong);
    cells = cells.slice().sort(function (x, y) {
      var fx = folderIndexOf(x.pid, x.dong), fy = folderIndexOf(y.pid, y.dong);
      return (fx - fy) || String(x.at || '').localeCompare(String(y.at || ''));
    });
    if ($('#photoInfo')) $('#photoInfo').textContent = (p ? p.name : '—') + ' ' + photoDongLabel(ui.photoPid, ui.photoDong) + ' · ' + weekRangeTxt(wk) +
      ' · 사진 ' + cells.length + '장 / 배정 접수 ' + awardApps.length + '건';
    if ($('#photoRetainInfo')) {
      photoPurgeExpired({});
      var nowCells = photosOfCell(wk, ui.photoPid, ui.photoDong);
      var soonN = nowCells.filter(function (ph) { var dd = photoDaysLeft(ph); return dd != null && dd > 0 && dd <= 14; }).length;
      $('#photoRetainInfo').textContent = '보관기간 등록일로부터 3개월(90일) · 기간 경과 시 자동 삭제 — 이 화면 ' + nowCells.length + '장' +
        (soonN ? ' · 삭제 임박 ' + soonN + '장' : '');
    }
    if ($('#photoAwardCount')) $('#photoAwardCount').textContent = awardApps.length + '건';
    if ($('#photoAwardList')) {
      $('#photoAwardList').innerHTML = awardApps.length
        ? '<table><thead><tr><th>접수번호</th><th>업체 · 실제 광고주</th><th style="text-align:right">배정</th><th>배정 위치</th><th>상태</th></tr></thead><tbody>' +
          awardApps.map(function (a) {
            var loc = awardedPlacesOf(a).filter(function (x) { return String(x.pid) === String(ui.photoPid); })
              .map(function (x) { return x.slot ? slotName(boardById(x.pid), x.slot) : photoDongLabel(x.pid, dongLetterOfSlot(x.slot)); }).join(' · ');
            return '<tr><td class="mono">' + esc(a.id) + '</td>' +
              '<td><span class="co">' + esc(a.company) + '</span><span class="sm">' + esc(advOfApp(a).name) + '</span></td>' +
              '<td class="mono" style="text-align:right"><b>' + awardedOf(a) + '매</b></td>' +
              '<td class="sm">' + esc(loc || '—') + '</td><td>' + statusBadge(a.status) + '</td></tr>';
          }).join('') + '</tbody></table>'
        : '<div class="photo-empty">이 주차 · 게시대 · 동에 배정된 접수가 없습니다. 주차·게시대·동을 바꿔 보세요.</div>';
    }
    if ($('#photoCount')) $('#photoCount').textContent = cells.length + '장' + (cells.length ? '' : ' — 아직 등록된 사진이 없습니다');
    if ($('#photoList')) {
      $('#photoList').innerHTML = cells.length
        ? cells.map(function (ph) { return photoCardHTML(ph, 'admin'); }).join('')
        : '<div class="photo-empty">등록된 게첨사진이 없습니다. <b>📁 사진 선택해서 올리기</b>로 현장 사진을 올리거나, <b>🧪 시연용 샘플 게첨사진 생성</b>으로 확인해 보세요.</div>';
    }
    if ($('#photoMsg')) $('#photoMsg').textContent = photoCanEdit() ? '' : '등록·삭제는 현장실무원·마스터만 가능합니다.';
    if ($('#photoFolderGrid')) {
      var q = String(ui.photoFolderQuery || '').trim().toLowerCase();
      var fmode = ui.photoFolderFilter || 'all';
      var folderCards = [], totalCards = 0, doneCards = 0;
      pids.forEach(function (fid) {
        var bp = boardById(fid);
        var bLetters = (bp ? boardLettersOf(bp) : ['']).slice().sort(function (x, y) { return folderIndexOf(fid, x) - folderIndexOf(fid, y); });
        bLetters.forEach(function (fl) {
          var fApps = photoAppsOfCell(wk, fid, fl);
          var fPhotos = photosOfCell(wk, fid, fl);
          totalCards += 1;
          if (fPhotos.length) doneCards += 1;
          var bName = bp ? bp.name : fid;
          if (q && bName.toLowerCase().indexOf(q) < 0 && photoDongLabel(fid, fl).toLowerCase().indexOf(q) < 0) return;
          if (fmode === 'todo' && fPhotos.length > 0) return;
          if (fmode === 'done' && fPhotos.length === 0) return;
          var isOn = (String(fid) === String(ui.photoPid) && String(fl) === String(ui.photoDong));
          var thumbs = fPhotos.slice(0, 3).map(function (ph) {
            return '<img src="' + photoDataOf(ph) + '" alt="' + esc(bName) + '">';
          }).join('');
          folderCards.push(
            '<div class="photo-folder-card' + (fPhotos.length ? ' done' : '') + (isOn ? ' active' : '') + '" data-pffolder="' + esc(fid) + '" data-pfdong="' + esc(fl) + '">' +
              '<div class="pfc-top"><div><div class="pfc-title">📁 ' + esc(bName) + ' · ' + esc(photoDongLabel(fid, fl)) + '</div>' +
              '<div class="pfc-sub">배정 ' + fApps.length + '건 · ' + esc(photoFolderName({ pid: fid, dong: fl }).replace(/^_/, '')) + '</div></div>' +
              '<span class="pfc-badge ' + (fPhotos.length ? 'ok' : 'wait') + '">' + (fPhotos.length ? ('✅ ' + fPhotos.length + '장') : '미등록') + '</span></div>' +
              (thumbs ? ('<div class="pfc-thumbs">' + thumbs + '</div>') : '<div class="pfc-drop">여기에 사진 파일을 끌어다 놓으세요</div>') +
              '<div class="pfc-actions"><span class="sm">' + (fPhotos.length ? '추가 드래그 가능' : '클릭 또는 드롭') + '</span>' +
              '<button class="btn sm ghost" type="button" data-pfpick="' + esc(fid) + '" data-pfdong="' + esc(fl) + '">+ 사진 올리기</button></div>' +
            '</div>'
          );
        });
      });
      if ($('#photoFolderSummary')) $('#photoFolderSummary').textContent = weekRangeTxt(wk) + ' · 폴더 ' + totalCards + '개 중 ' + doneCards + '개 등록완료';
      $('#photoFolderGrid').innerHTML = folderCards.length
        ? folderCards.join('')
        : '<div class="photo-empty">조건에 맞는 게시대 폴더가 없습니다. 검색어나 필터를 바꿔 보세요.</div>';
    }
  }

  /* ---------------------------------------------------------------
     8. 미배정(선착순) 예약
     --------------------------------------------------------------- */
  /* 선착순 접수 창구 — 목요일 00:00~24:00 하루만, 금요일은 접수 제한 */
  /* ── 목요일 잔여석 선착순 · 입고 마감 (2026-11-22 김재봉 님 지시로 변경) ──
     · 접수 가능 시간: 목요일 **일과시간 09:00~18:00** (그 외 시간·금요일은 접수 불가)
     · 목요일 선착순 당첨분 입고 마감: **금요일 10:00** — 미입고 시 자동 취소(반려)
     · 시연을 위해 '목요일'·'일과시간/18시 이후'를 화면에서 바꿔 볼 수 있다. */
  var FC_OPEN_FROM = 9, FC_OPEN_TO = 18;
  /* 선착순(취소분) 당첨분 입고 마감 — 금요일 10:00 / 목요일이 공휴일인 주는 금요일 14:00 */
  var FC_DELIVER = {};
  Object.defineProperty(FC_DELIVER, 'date', { enumerable: true, get: function () { return ROUND.cutoffDate; } });
  Object.defineProperty(FC_DELIVER, 'time', { enumerable: true, get: function () { return isThuHoliday() ? '14:00' : '10:00'; } });

  /* ── 진행 중 주간(이번 주 게첨) 잔여석 접수 — 김재봉 님 지시 2026-11-23 ─────────
     "현재 진행 중인 주간에 잔여석 접수 열어주고 / 광고사에겐 직접설치 해야된다 메세지 /
      일반인에겐 광고사의뢰 메세지."
     · 11.23~11.29(11월 4주차)는 협회 일괄 게첨(추첨 → 입고 → 게첨)이 이미 끝난 주간입니다.
       그래서 남은 면은 **요일·일과시간 제한 없이** 지금 바로 접수할 수 있게 엽니다.
     · 설치 주체가 협회가 아니므로 접수자 유형에 따라 안내 문구를 나눕니다.
       광고대행사(광고사) → 광고사가 직접 현장 설치 /
       일반인(일반업체·일반회원·비회원) → **규정상 직접 설치 금지** — 반드시 옥외광고업 등록 광고사에 의뢰 */
  var LIVE_MSG = {
    agency: '⚠️ 진행 중 주간 잔여석 접수입니다. 접수 후 반드시 협회에서 검인 도장을 찍은 뒤, 광고사에서 직접 현장에 설치(게첨)하셔야 합니다.',
    general: '⚠️ 진행 중 주간 잔여석 접수입니다. 관련 규정에 따라 일반인은 직접 설치가 금지되어 있으므로, 접수 후 반드시 협회에서 검인 도장을 찍은 뒤 옥외광고업 등록 광고사에 설치를 의뢰하셔야 합니다.'
  };
  var LIVE_MSG_HTML = {
    agency: '⚠️ 진행 중 주간 잔여석 접수입니다. 접수 후 <b>반드시 협회에서 검인 도장을 찍은 뒤</b>, <b>광고사에서 직접 현장에 설치(게첨)</b>하셔야 합니다.',
    general: '⚠️ 진행 중 주간 잔여석 접수입니다. 관련 규정에 따라 <b>일반인은 직접 설치가 금지</b>되어 있으므로, 접수 후 <b>반드시 협회에서 검인 도장을 찍은 뒤 옥외광고업 등록 광고사에 설치를 의뢰</b>하셔야 합니다.'
  };
  /* 명절·연휴·휴가 주간 직접설치 — 진행 주간 접수와 100% 같은 분기 (2026-11-23 김재봉 님 지시) */
  var HOLIDAY_MSG = {
    agency: '⚠️ 명절·연휴·휴가 주간 직접설치 안내: 접수 후 반드시 협회에서 검인 도장을 찍은 뒤, 광고사에서 직접 현장에 설치(게첨)하셔야 합니다.',
    general: '⚠️ 명절·연휴·휴가 주간 직접설치 안내: 관련 규정에 따라 일반인은 직접 설치가 금지되어 있으므로, 접수 후 반드시 협회에서 검인 도장을 찍은 뒤 옥외광고업 등록 광고사에 설치를 의뢰하셔야 합니다.'
  };
  var HOLIDAY_MSG_HTML = {
    agency: '⚠️ <b>명절·연휴·휴가 주간 직접설치 안내</b>: 접수 후 <b>반드시 협회에서 검인 도장을 찍은 뒤, 광고사에서 직접 현장에 설치(게첨)</b>하셔야 합니다.',
    general: '⚠️ <b>명절·연휴·휴가 주간 직접설치 안내</b>: 관련 규정에 따라 <b>일반인은 직접 설치가 금지</b>되어 있으므로, 접수 후 <b>반드시 협회에서 검인 도장을 찍은 뒤 옥외광고업 등록 광고사에 설치를 의뢰</b>하셔야 합니다.'
  };
  function holidayInstallMsg(kind) { return HOLIDAY_MSG[kind === 'agency' ? 'agency' : 'general']; }
  function holidayInstallHTML(kind) { return HOLIDAY_MSG_HTML[kind === 'agency' ? 'agency' : 'general']; }
  /* 직접설치 안내 멘트 — 명절·연휴·휴가 주간 정책이 켜져 있으면 그 문구를 쓴다 */
  function directInstallMsgOf(kind) { return holidayDirectInstallOn() ? holidayInstallMsg(kind) : liveMsgOf(kind); }
  function directInstallHTMLOf(kind) { return holidayDirectInstallOn() ? holidayInstallHTML(kind) : liveMsgHTMLOf(kind); }
  function directInstallKindLabel() { return holidayDirectInstallOn() ? '명절·연휴·휴가 주간 직접설치' : '진행 중 주간 잔여석 접수'; }
  /* 접수증·마이페이지에서 쓰는 검인 안내 한 줄 */
  function liveSealNote(kind) {
    return kind === 'agency'
      ? '협회 검인(도장) 필수 — 접수 후 협회에서 검인 도장을 찍은 뒤 광고사가 직접 현장에 게첨합니다.'
      : '협회 검인(도장) 필수 — 접수 후 협회에서 검인 도장을 찍은 뒤 옥외광고업 등록 광고사에 설치를 의뢰합니다.';
  }
  function liveInstallLabel(kind) {
    return kind === 'agency' ? '광고사 직접 설치' : '광고사 의뢰 (일반인 직접설치 금지)';
  }
  function liveInstallKindOf(a) {
    if (!a) return 'general';
    if (a.installType === 'agency' || a.installType === 'general') return a.installType;
    return a.appType === 'agency' ? 'agency' : 'general';
  }
  function liveMsgOf(kind) { return LIVE_MSG[kind === 'agency' ? 'agency' : 'general']; }
  function liveMsgHTMLOf(kind) { return LIVE_MSG_HTML[kind === 'agency' ? 'agency' : 'general']; }
  /* 로그인 회원 구분 — 광고대행사면 '광고사 직접 설치', 그 외(일반업체·비회원)는 '광고사 의뢰'(일반인 직접설치 금지) */
  function applicantKind() { var m = currentMember(); return (m && m.type === 'agency') ? 'agency' : 'general'; }
  function liveWeekOpenNow() { return todayISO() <= CUR.end; }
  /* 진행 중 주간 잔여 면 — 그 주(11.23~11.29) 확정·공문 배정을 뺀 실제 빈 칸 수 */
  function liveAvailOf(p) {
    if (!p || p.broken) return 0;
    var plan = slotPlan(p.id, CUR.start);
    return Math.max(0, plan.free.length);
  }
  function liveLeftTotal() {
    var n = 0;
    db.placements.forEach(function (p) { n += liveAvailOf(p); });
    return n;
  }
  function liveWeekState() {
    var open = liveWeekOpenNow();
    return {
      open: open, kind: open ? 'open' : 'closed', id: CUR.id, label: CUR.label,
      start: CUR.start, end: CUR.end, left: liveLeftTotal(),
      badge: open ? '진행 중 주간 접수 중 (제한 없음)' : '진행 주간 접수 종료',
      title: open ? '진행 중 주간 잔여석 접수 중 (' + dfmt(CUR.start) + ' ~ ' + dfmt(CUR.end) + ')'
        : '진행 중 주간 접수 기간이 지났습니다',
      msg: open
        ? '협회 일괄 게첨이 끝난 주간입니다 — 남은 잔여 면을 요일·일과시간 제한 없이 지금 바로 접수할 수 있습니다.'
        : '이번 주 게첨 주간(' + dfmt(CUR.start) + ' ~ ' + dfmt(CUR.end) + ')이 끝나 잔여석 접수를 마감했습니다. 다음 회차는 미배정 선착순(목요일 일과시간)으로 접수합니다.'
    };
  }
  function setFcMode(m) {
    ui.fcMode = (m === 'next' ? 'next' : 'live');
    renderFirst();
    return ui.fcMode;
  }
  function firstComeOpenNow() {
    if (ui.fcTimeSim === 'after') return false;
    if (ui.fcTimeSim === 'open') return true;
    var h = getNow().getHours();
    return h >= FC_OPEN_FROM && h < FC_OPEN_TO;
  }
  function firstComeState() {
    var today = getNow().getDay();
    var d = ui.daySim === 'thu' ? 4 : (ui.daySim === 'fri' ? 5 : today);
    var hol = isThuHoliday(), openDow = fcOpenDow(), dayName = fcOpenDayName();
    var fcDayTxt = dfmt(isThuHoliday() ? addDays(ROUND.firstComeDate, 1) : ROUND.firstComeDate);
    if (hol && d === 4) return { open: false, kind: 'holiday', badge: '목요일 공휴일 · 금요일로 변경',
      title: '목요일 공휴일 — 취소분 선착순은 금요일로 변경',
      msg: '이번 주 목요일은 공휴일(' + thuHolidayLabel() + ')입니다. 취소분 선착순 접수는 금요일(09:00~18:00)에 진행하며, 선착순 당첨분 현수막 입고 마감은 금요일 14:00입니다.' };
    if (d === 3) return { open: false, kind: 'wait', badge: '수 18:00 반려 후 공개',
      title: '수요일 · 18:00 미입고 반려 후 공개',
      msg: '오늘 18:00에 미입고분을 일괄 반려하고, ' + fcDayTxt + ' 09:00(일과시간 시작)부터 선착순 접수를 시작합니다.' };
    if (d === openDow) {
      /* 시연에서 접수일(목요일 · 공휴일이면 금요일)을 고르면 기본은 일과시간(접수 가능) — '18시 이후'를 고르면 닫힘 */
      var simKey = (openDow === 4 ? 'thu' : 'fri');
      var open = (ui.daySim === simKey && ui.fcTimeSim !== 'after') || (!ui.daySim && firstComeOpenNow());
      if (open) return { open: true, kind: 'open', badge: dayName + ' 선착순 접수 중 (09:00~18:00)',
        title: dayName + ' · ' + (hol ? '취소분 선착순 접수 중 (목요일 공휴일 → 금요일)' : '잔여석 선착순 접수 중') + ' (일과시간 09:00~18:00)',
        msg: dayName + ' 일과시간(09:00~18:00)에만 접수합니다. 누르는 즉시 확정되며, 수수료 입금과 현수막 실물은 ' + dfmt(FC_DELIVER.date) + ' ' + FC_DELIVER.time + '까지 입고해야 합니다. (미입고 시 자동 취소)' };
      return { open: false, kind: 'offhours', badge: dayName + ' · 일과시간 아님 (09:00~18:00)',
        title: dayName + ' · 일과시간(09:00~18:00)에만 접수합니다',
        msg: '잔여석 선착순 접수는 ' + dayName + ' 일과시간 09:00~18:00에만 가능합니다. 지금은 접수 시간이 아닙니다. (시연용으로 아래 [일과시간]을 눌러 접수 화면을 확인할 수 있습니다.)' };
    }
    if (d === 5) return { open: false, kind: 'closed', badge: '금요일 · 접수 제한',
      title: '금요일 · 잔여석 접수 제한',
      msg: '현장 게첨 작업 준비로 인해 금요일은 잔여석 접수가 제한됩니다. 목요일 선착순 당첨분은 ' + dfmt(FC_DELIVER.date) + ' ' + FC_DELIVER.time + '까지 입고해야 하며, 미입고 시 자동 취소(반려)됩니다.' };
    return { open: false, kind: 'wait', badge: WEEK_DAYS[d] + '요일 · 접수 시간 아님',
      title: WEEK_DAYS[d] + '요일 · 접수 시간이 아닙니다',
      msg: '선착순 접수는 ' + fcDayTxt + ' 일과시간 <b>09:00 ~ 18:00</b>에만 운영합니다.' +
        (hol ? ' (이번 주 목요일은 공휴일이라 금요일로 변경되었습니다.)' : '') };
  }

  /* ═════════════════════════════════════════════════════════════════════════
     first.html — 미배정 선착순(잔여석) 접수 · 주간 추첨 접수(apply.html)와 같은 4단계 흐름
     (2026-11-23 김재봉 님 지시 "미배정 잔여 접수도 주간추첨이랑 같은 흐름으로")
       ① 실제 광고주·문구·시안 → ② 창구·수량 → ③ 게시대 선택 → ④ 확인·접수
     · 3단계 = 잔여 게시대 '한 줄 보기' 목록에서 담기 (정치행정 게시대 제외)
     · 4단계 = 수수료 · 설치 방식 확인 → [접수 제출] · 안내문구는 화면 하단
     ═════════════════════════════════════════════════════════════════════════ */
  var FC_STEP_HINT = [
    '1단계 · 실제 광고주 · 현수막 문구 · 시안을 등록해 주세요.',
    '2단계 · 접수 창구와 신청 수량(잔여 매수 범위 안)을 골라 주세요.',
    '3단계 · 신청 수량만큼 서로 다른 게시대를 골라 주세요. (1개소 1매)',
    '4단계 · 수수료와 설치 방식을 확인하고 [접수 제출]을 눌러 주세요.'
  ];

  /* 두 창구를 별도 페이지로 분리 (2026-11-23 김재봉 님 지시)
     · remain.html = ⚡ 미배정 상시접수 — 추첨 미배정 잔여 자리, 요일·시간 제한 없음
     · first.html  = 🔥 취소분 선착순 — 수요일 18:00 미입금·미입고 취소분만, 목요일 09:00~18:00 */
  function fcPageRemain() { return PAGE === 'remain'; }
  function fcIsLive() { return fcPageRemain() || ui.fcMode === 'live'; }
  /* 정치행정(공문 전용 저단) 게시대는 미배정 선착순 목록에서 제외한다 */
  function fcBoardOk(p) { return !!p && !p.low && !p.officialOnly; }
  /* 지금 창구(진행 중 주간 / 목요일 선착순)에서 이 게시대에 남은 면 */
  function fcLeftOf(p) {
    if (!p || p.broken || slotAllDown(p) || !fcBoardOk(p)) return 0;
    if (fcPageRemain()) return slotPlan(p.id, fcWeek()).free.length;   /* 선택한 게철 주의 미배정 잔여 면 */
    return Math.min(fcCancelSeatsOf(p), fcAvailOf(p));         /* 취소분(회수·취소 배정)만 */
  }
  /* ── remain.html — 1단계 게철 희망 날짜(주차) 선택 (2026-11-23 김재봉 님 지시) ──
     "미배정 접수는 날짜선택이 첫 페이지에 만들어줘." — 이번 주 진행 중 주간 / 다음 주 이후 잔여석 */
  function fcWeekChoices() {
    /* 미배정 상시접수는 **이미 추첨이 끝난 주차만** — 아직 추첨 전인 미래 주차는 주간 추첨 접수(apply) 대상
       (2026-11-23 김재봉 님 지시 "미배정상시접수에서 아직 추첨안된건 노출시키지마") */
    var cur = weekStartOf(CUR.start), out = [];
    out.push({ wk: cur, cur: true, label: '이번 주 진행 중', range: dstr(CUR.start) + '~' + dstr(CUR.end) });
    var drawnRounds = {};
    (db.draws || []).forEach(function (d) { if (d && d.round) drawnRounds[d.round] = 1; });
    [ROUND.postStart, addDays(ROUND.postStart, 7)].forEach(function (s, i) {
      var wk = weekStartOf(s);
      if (!drawnRounds[weekRoundId(wk)]) return;         /* 추첨 완료된 주차만 */
      var meta = weekMeta(weekRoundId(wk)) || {};
      out.push({ wk: wk, cur: false, label: meta.label || (i === 0 ? '다음 주' : '그다음 주'), range: dstr(wk) + '~' + dstr(addDays(wk, 6)) });
    });
    return out;
  }
  function fcWeek() {
    var list = fcWeekChoices();
    if (!fcIsLive()) return weekStartOf(CUR.start);
    var hit = null;
    if (!fcPageRemain()) { ui.fcWeek = weekStartOf(CUR.start); return ui.fcWeek; }
    for (var i = 0; i < list.length; i++) { if (list[i].wk === ui.fcWeek) hit = list[i]; }
    if (!hit) { ui.fcWeek = list[0].wk; hit = list[0]; }
    return hit.wk;
  }
  function fcWeekMeta() {
    var list = fcWeekChoices(), wk = fcIsLive() ? fcWeek() : weekStartOf(CUR.start);
    for (var i = 0; i < list.length; i++) { if (list[i].wk === wk) return list[i]; }
    return list[0];
  }
  function fcWeekPickHTML() {
    if (!fcPageRemain() || !has('fcWeekPick')) return '';
    var cur = fcWeek();
    $('#fcWeekPick').innerHTML = fcWeekChoices().map(function (x) {
      var on = x.wk === cur;
      return '<button class="chip' + (on ? ' active' : '') + '" type="button" data-fcweek="' + x.wk + '" ' +
        'title="' + esc(x.label + ' ' + x.range + ' 게철 주') + '">' + esc(x.label) + ' <em style="font-style:normal;font-weight:600;color:var(--muted)">(' + esc(x.range) + ')</em></button>';
    }).join('') +
      '<span class="hint-txt" style="margin:0 0 0 6px">선택한 주차: <b>' + esc(fcWeekMeta().label + ' ' + fcWeekMeta().range) + '</b></span>';
    return cur;
  }
  function setFcWeek(wk) {
    if (!fcPageRemain()) return fcWeek();
    ui.fcWeek = weekStartOf(wk || CUR.start);
    ui.fcPicks = [];
    ui.fcQty = QTY_MIN;
    renderFirst();
    return ui.fcWeek;
  }
  /* 취소분 — 수요일 18:00 미입금·미입고·본인취소로 회수된 자리 (목요일 선착순 대상) */
  function fcCancelSeatsOf(p) {
    var n = reclaimedOf(p);
    var wk = weekStartOf(ROUND.postStart);
    db.apps.forEach(function (a) {
      if (!a || ['미입고취소', '미입금취소', '본인취소'].indexOf(a.status) < 0) return;
      if (weekStartOf(a.start || ROUND.postStart) !== wk) return;
      awardedPlacesOf(a).forEach(function (pl) { if (pl && pl.pid === p.id) n += 1; });
    });
    return n;
  }
  function fcLeftTotal() {
    var n = 0;
    db.placements.forEach(function (p) { n += fcLeftOf(p); });
    return n;
  }
  function fcMaxQty() { return Math.max(0, Math.min(QTY_MAX, fcLeftTotal())); }
  function fcPicks() { if (!Array.isArray(ui.fcPicks)) ui.fcPicks = []; return ui.fcPicks; }
  function fcPickedIn(pid) { return fcPicks().indexOf(pid) >= 0; }
  function fcQtyVal() {
    var el = $('#fcQty');
    var raw = el ? String(el.value == null ? '' : el.value).trim() : '';
    var n = Number(raw.replace(/[^0-9]/g, ''));
    return isNaN(n) ? 0 : n;
  }
  function fcSessionState() {
    if (fcIsLive()) {
      var wm0 = fcWeekMeta();
      return { open: true, kind: 'open', badge: '상시접수 가능 (요일·시간 제한 없음)',
        title: '미배정 잔여 자리 상시접수 — ' + wm0.label + ' (' + wm0.range + ')', id: wm0.cur ? CUR.id : weekRoundId(wm0.wk), label: wm0.label,
        msg: wm0.cur
          ? '추첨에서 배정되지 않은 이번 주 잔여 자리를 요일·일과시간 제한 없이 지금 바로 접수할 수 있습니다.'
          : wm0.label + '(' + wm0.range + ') 게철 주의 미배정 잔여 자리를 사전 접수합니다 — 추첨 없이 잔여 면부터 선착순으로 확정됩니다.' };
    }
    return firstComeState();
  }
  function fcSessionOpen() { return !!fcSessionState().open; }
  function fcQtyNow() { return (ui.fcQty && ui.fcQty >= QTY_MIN) ? ui.fcQty : QTY_MIN; }

  function setFcMode(m) {
    ui.fcMode = (m === 'next' ? 'next' : 'live');
    ui.fcQty = QTY_MIN;
    ui.fcPicks = [];
    ui.liveKind = '';
    renderFirst();
    return ui.fcMode;
  }

  /* 접수 창구 모드 칩 — 진행 중 주간(지금 바로) / 이번 회차 목요일 선착순 */
  function fcModeChipsHTML() {
    var lab = '<span style="font-size:12px;color:var(--muted);font-weight:700;align-self:center;margin-right:2px">접수 창구</span>';
    if (fcPageRemain()) {
      var wm = fcWeekMeta();
      return lab + '<button class="chip active" type="button" title="미배정 잔여 자리 — 요일·시간 제한 없이 상시 접수">' +
        '⚡ 미배정 상시접수 (' + esc(wm.label) + ' ' + esc(wm.range) + ' · ' + (wm.cur ? '제한 없음' : '사전 접수') + ')</button>';
    }
    return lab + '<button class="chip active" type="button" title="수요일 18:00 미입금·미입고로 취소된 자리 — ' + fcOpenDayName() + ' 일과시간 선착순">' +
      '🔥 취소분 선착순 (' + esc(ROUND.label) + ' · ' + fcOpenDayName() + ' 09:00~18:00' + (isThuHoliday() ? ' · 목요일 공휴일' : '') + ')</button>';
  }
  /* 시연 기준일·시간 칩 — 목요일 선착순 창구에서만 노출 */
  function fcDayChipsHTML() {
    return '<span style="font-size:12px;color:var(--muted);font-weight:700;align-self:center;margin-right:2px">시연 기준일</span>' +
      [['', '오늘(' + WEEK_DAYS[getNow().getDay()] + ')'], ['thu', '목요일'], ['fri', '금요일']].map(function (x) {
        var on = (x[0] === '' && !ui.daySim) || (x[0] !== '' && ui.daySim === x[0]);
        return '<button class="chip' + (on ? ' active' : '') + '" data-fcday="' + x[0] + '" type="button">' + x[1] + '</button>';
      }).join('') +
      '<span style="font-size:12px;color:var(--muted);font-weight:700;align-self:center;margin-left:8px;margin-right:2px">시연 시간</span>' +
      [['open', '일과시간(09~18)'], ['after', '18시 이후']].map(function (x) {
        var on = (x[0] === 'after' && ui.fcTimeSim === 'after') || (x[0] === 'open' && ui.fcTimeSim !== 'after');
        return '<button class="chip' + (on ? ' active' : '') + '" data-fctime="' + x[0] + '" type="button">' + x[1] + '</button>';
      }).join('');
  }
  /* 창구 상태 배너 — 진행 중 주간이면 설치 주체(검인 후 직접설치/광고사 의뢰)까지 함께 안내 */
  function fcBannerHTML() {
    var st = fcSessionState();
    var icon = st.open ? IC.check : (st.kind === 'closed' ? IC.x : IC.clock);
    var html = '<div class="fc-window ' + st.kind + '">' + icon +
      '<div><b>' + esc(st.title) + '</b><span>' + esc(st.msg) + '</span></div></div>';
    /* 명절·연휴·휴가 주간 직접설치 전환 — 진행 중 주간 접수와 같은 안내 멘트 (선택한 게첨 주 기준) */
    if (holidayDirectInstallOn(ui.fcWeek)) {
      var hk = ui.liveKind || applicantKind();
      html += '<div class="callout warn" id="fcLiveMsg">' + IC.alert +
        '<div>' + directInstallHTMLOf(fcIsLive() ? hk : hk) +
        '<span class="sm" style="display:block;margin-top:4px">' +
          (hk === 'agency'
            ? '광고대행사(광고사) 접수 — 협회가 게첨하지 않으므로 직접 현장에 설치해 주세요.'
            : '일반업체·비회원 접수 — 관련 규정상 직접 설치가 금지되어 있으므로 반드시 광고사에 의뢰해 주세요.') +
        '</span></div></div>';
      return html;
    }
    if (fcIsLive()) {
      var kind = ui.liveKind || applicantKind();
      html += '<div class="callout warn" id="fcLiveMsg">' + IC.alert +
        '<div>' + liveMsgHTMLOf(kind) +
        '<span class="sm" style="display:block;margin-top:4px">' +
          (kind === 'agency'
            ? '광고대행사(광고사) 접수 — 협회가 게첨하지 않으므로 직접 현장에 설치해 주세요.'
            : '일반업체·비회원 접수 — 관련 규정상 직접 설치가 금지되어 있으므로 반드시 광고사에 의뢰해 주세요.') +
        '</span></div></div>';
    }
    return html;
  }

  /* ── 4단계 공통 렌더 ─────────────────────────────────────────────────── */
  function renderFirst() {
    if (!has('firstList')) return;
    if (!ui.fcStep) ui.fcStep = 1;
    var mx = fcMaxQty();
    if (!ui.fcQty || ui.fcQty < QTY_MIN) ui.fcQty = QTY_MIN;
    if (mx && ui.fcQty > mx) ui.fcQty = mx;
    /* 잔여가 사라진 게시대는 담기에서 제외 */
    ui.fcPicks = fcPicks().filter(function (id) { var p = placementById(id); return p && fcLeftOf(p) > 0; });
    if (ui.fcPicks.length > fcQtyNow()) ui.fcPicks = ui.fcPicks.slice(0, fcQtyNow());
    renderFcHead();
    renderFcStep1();
    renderFcStep2();
    renderFcStep3();
    renderFcStep4();
    renderFcFoot();
  }

  function renderFcHead() {
    var st = fcSessionState();
    if (fcPageRemain()) {
      if ($('#firstRoundLine')) $('#firstRoundLine').textContent = CUR.label + ' 게시분 (' + dstr(CUR.start) + ' ~ ' + dstr(CUR.end) + ') · ' +
        '추첨에서 배정되지 않은 잔여 자리를 요일·일과시간 제한 없이 상시 접수합니다.';
      if ($('#roundName')) $('#roundName').textContent = CUR.label + ' 상시접수';
      if ($('#roundDue')) $('#roundDue').textContent = '게첨 ' + dstr(CUR.start) + '~' + dstr(CUR.end);
    } else {
      if ($('#firstRoundLine')) $('#firstRoundLine').textContent = ROUND.label + ' 게시분 (' + dfmt(ROUND.postStart) + ' ~ ' + dfmt(ROUND.postEnd) + ') · ' +
        '수요일 18:00 미입금·미입고로 취소된 자리만 목요일 일과시간(09:00~18:00)에 선착순 접수합니다.';
      if ($('#roundName')) $('#roundName').textContent = ROUND.label + ' 주간 추첨';
      if ($('#roundDue')) $('#roundDue').textContent = '입고 마감 ' + dfmt(ROUND.deliverBy);
    }
    var chip = $('#fcBadge');
    if (chip) {
      chip.className = 'badge ' + (st.open ? 'b-green' : (st.kind === 'closed' ? 'b-red' : 'b-amber'));
      chip.innerHTML = '<i></i>' + esc(st.badge);
    }
  }

  /* 1단계 — 실제 광고주 · 문구 · 시안 (로그인 정보 박스 없이 최상단 / 등록증은 일반인만) */
  function renderFcStep1() {
    var kind = applicantKind();
    var wrap = $('#fcLicWrapEl');
    if (wrap) {
      if (kind === 'agency') {
        wrap.innerHTML = '';
        wrap.classList.add('hidden');
        wrap.setAttribute('data-kind', 'agency');
      } else {
        if (wrap.getAttribute('data-kind') !== 'general') {
          wrap.innerHTML = fcLicBoxHTML();
          wrap.setAttribute('data-kind', 'general');
          if (!ui.fcLic || !ui.fcLic.name) ui.fcLic = { name: '', no: '', src: '', fail: false };
          renderFcLic();
          bindFcLic();
        }
        wrap.classList.remove('hidden');
      }
    }
    /* 일반업체 회원만 광고주 칸을 회원사명으로 비워 두면 채워 준다 (광고대행사는 실제 광고주가 따로이므로 비워 둔다) */
    var m = currentMember(), el = $('#fcAdvertiser');
    if (m && el && kind !== 'agency' && !String(el.value || '').trim()) el.value = m.company || '';
    if ($('#fcTextCount')) $('#fcTextCount').textContent = String(String(($('#fcText') ? $('#fcText').value : '') || '').length);
    /* remain.html — 1단계 상단 게철 희망 날짜(주차) 선택 */
    try { fcWeekPickHTML(); } catch (e) { }
    syncFcMedicalNote();
    syncFcAbuseNote();
    try { syncYouthNote('#fcYouthNote', String(($('#fcAdvertiser') ? $('#fcAdvertiser').value : '') || '') + ' ' + String(($('#fcText') ? $('#fcText').value : '') || '')); } catch (e) { }
  }

  /* 2단계 — 창구 선택 · 신청 수량 · 설치 안내 */
  function renderFcStep2() {
    if ($('#fcModeChips')) $('#fcModeChips').innerHTML = fcModeChipsHTML();
    if ($('#fcDayChips')) {
      $('#fcDayChips').innerHTML = fcIsLive()
        ? '<span class="hint-txt" style="margin:0">진행 중 주간은 요일·일과시간 제한 없이 접수합니다.</span>'
        : fcDayChipsHTML();
    }
    if ($('#fcBanner')) $('#fcBanner').innerHTML = fcBannerHTML();
    var mx = fcMaxQty(), left = fcLeftTotal();
    if ($('#firstCount')) $('#firstCount').textContent = '잔여 ' + left + '매' + (brokenCount() ? ' (고장 ' + brokenCount() + '개소 제외)' : '');
    var q = $('#fcQty');
    if (q) {
      if (String(q.value) !== String(fcQtyNow())) q.value = String(fcQtyNow());
      q.setAttribute('max', String(Math.max(1, mx || 1)));
    }
    if ($('#fcQtyHint')) {
      $('#fcQtyHint').innerHTML = '지금 접수할 수 있는 잔여 매수는 <b>' + left + '매</b>입니다 — 한 번에 <b>1매 ~ ' +
        Math.max(1, mx) + '매</b>까지 신청할 수 있고, 3단계에서 <b>1개소당 1매씩</b> 서로 다른 게시대를 고릅니다.';
    }
    if ($('#fcLeftInfo')) {
      $('#fcLeftInfo').innerHTML = '<dl>' +
        '<dt>접수 창구</dt><dd>' + (fcIsLive()
          ? '🔥 진행 중 주간 잔여석 (' + dstr(CUR.start) + '~' + dstr(CUR.end) + ' · 요일·시간 제한 없음)'
          : esc(ROUND.label) + ' 선착순 (목요일 일과시간 09:00~18:00)') + '</dd>' +
        '<dt>잔여 매수</dt><dd><b>' + left + '매</b> · 고장 게시대 ' + brokenCount() + '개소 제외</dd>' +
        '</dl>';
    }
  }

  /* 3단계 — 잔여 게시대 한 줄 보기 목록에서 담기 */
  function fcCoverSeatsOf(p) {
    var plan = slotPlan(p.id, fcIsLive() ? CUR.start : ROUND.postStart);
    return plan.free.filter(function (c) {
      if (slotIsCover(p, c)) return true;
      var o = slotOtherOf(p, c);
      return !!o && o.mode === 'warn';
    });
  }
  function fcListHTML() {
    var picks = fcPicks(), open = fcSessionOpen();
    var rows = db.placements.filter(function (p) {
      if (!fcBoardOk(p)) return false;
      if (ui.fcTheme && (p.themes || []).indexOf(ui.fcTheme) < 0) return false;
      return true;
    });
    if (!rows.length) return '<div class="empty"><div>조건에 맞는 게시대가 없습니다. 테마 필터를 [전체]로 바꿔 주세요.</div></div>';
    return rows.map(function (p) {
      var rem = fcLeftOf(p), picked = picks.indexOf(p.id) >= 0;
      var bk = p.broken || slotAllDown(p);
      var fsum = slotFlagSummary(p), rec = fcIsLive() ? 0 : reclaimedOf(p);
      var yBlocked = p.youthProtect && youthHitOf(((($('#fcAdvertiser') || {}).value) || '') + ' ' + ((($('#fcText') || {}).value) || ''));
      var label = yBlocked ? '🚫 청소년유해 차단'
        : (picked ? '담김 ✓'
        : (p.broken ? '고장·수리중'
          : (slotAllDown(p) ? '전체 고장·풀가림'
            : (!rem ? '마감' : (open ? '담기' : '접수 시간 아님')))));
      var coverBtn = (!fcIsLive() && !bk && rem && fcCoverSeatsOf(p).length)
        ? ' <button class="btn sm ghost fc-cover-btn" data-fccover="' + esc(p.id) + '" type="button" title="풀가림·기타사유 단수 선택 — 안내 확인 후 담기">풀가림·기타 자리</button>'
        : '';
      return '<div class="fc-item' + (picked ? ' picked' : '') + '">' +
        '<div class="fmain"><b>' + esc(p.name) +
        (p.youthProtect ? ' <span class="tag broken">🚸 초인접</span>' : '') +
        (p.broken ? ' <span class="tag broken">고장·수리중</span>'
          : (fsum ? ' <span class="tag broken">' + esc(fsum) + '</span>'
            : (rec ? ' <span class="tag hot">미입고 회수 ' + rec + '면</span>' : ''))) + coverBtn + '</b>' +
        '<span>' + esc(p.dong) + ' · ' + esc(p.day) + '요일 설치' +
          (p.broken ? ' · 수리중 (가용 면 제외)'
            : (fsum ? ' · ' + esc(fsum) + (fcIsLive() ? '' : ' · 풀가림·기타는 목요일 선착순만') : '')) +
          (dongPriorityShort(p) ? ' · ' + esc(dongPriorityShort(p)) : '') + '</span></div>' +
        '<div class="fcount' + (rem ? '' : ' sold') + '"><b>' + rem + '</b><span>' + (p.broken ? '가용 면 제외' : (fcIsLive() ? '잔여 면' : '잔여 매')) + '</span></div>' +
        fcActHTML(p, '<button class="btn sm ' + (picked ? 'ok' : (label === '담기' ? 'primary' : '')) + '" data-fcpick="' + p.id + '" type="button"' +
            ((open && rem && !bk && !yBlocked) ? '' : ' disabled') + '>' + label + '</button>') +
        '</div>';
    }).join('');
  }
  function renderFcStep3() {
    var picks = fcPicks(), q = fcQtyNow(), need = q - picks.length;
    if ($('#fcPickStatus')) {
      $('#fcPickStatus').innerHTML = (need > 0
        ? '<b style="color:var(--warn)">' + need + '개소 더 골라 주세요</b>'
        : '<b style="color:var(--ok)">수량을 모두 채웠습니다</b>') +
        ' — 신청 <b>' + q + '매</b> · 담은 게시대 <b>' + picks.length + '개소</b> (1개소 1매)';
    }
    if ($('#fcPickInfo')) $('#fcPickInfo').textContent = picks.length + '개소 / ' + q + '매';
    if ($('#fcPickSlots')) {
      $('#fcPickSlots').innerHTML = picks.length
        ? picks.map(function (pid, i) {
          var p = placementById(pid);
          if (!p) return '';
          return '<span class="slot filled">' + (i + 1) + '. ' + esc(p.name) +
            ' <button class="btn sm ghost" data-fcunpick="' + esc(pid) + '" type="button" title="선택 해제" aria-label="선택 해제">✕</button></span>';
        }).join('')
        : '<span class="hint-txt" style="margin:0">아직 담은 게시대가 없습니다 — 아래 목록에서 [담기]를 눌러 주세요.</span>';
    }
    if ($('#fcThemeChips')) $('#fcThemeChips').innerHTML = themeChipsHTML(ui.fcTheme, 'fctheme');
    if ($('#firstList')) $('#firstList').innerHTML = fcListHTML();
  }

  /* 4단계 — 수수료 · 설치 방식 확인 (안내문구는 아래) */
  function renderFcStep4() {
    var v = readFc(), picks = fcPicks(), f = feeFor(v.qty, 7);
    if ($('#fcSummary')) {
      var rows = [
        ['접수 창구', fcIsLive()
          ? '🔥 진행 중 주간 잔여석 (' + dstr(CUR.start) + '~' + dstr(CUR.end) + ' · 요일·시간 제한 없음)'
          : esc(ROUND.label) + ' 선착순 (목요일 일과시간 09:00~18:00)'],
        ['실제 광고주', esc((v.advertiser || '—') + (v.advertiserBiz ? ' · 사업자 ' + v.advertiserBiz : ''))],
        ['현수막 문구', esc(v.text || '—')],
        ['시안', esc(v.file ? v.file.name : '미첨부')],
        ['신청 수량', '<b>' + v.qty + '매</b> · 1개소 1매'],
        ['선택 게시대', picks.length
          ? picks.map(function (pid, i) {
            var p = placementById(pid);
            if (!p) return '';
            var slot = (ui.fcCover && ui.fcCover[pid]) || '';
            return (i + 1) + '. ' + esc(p.name) + (slot ? ' ' + esc(slotName(p, slot)) : '');
          }).join('<br>')
          : '미선택'],
        ['게시 기간', esc((fcIsLive() ? CUR.start : ROUND.postStart) + ' ~ ' + addDays((fcIsLive() ? CUR.start : ROUND.postStart), 6) + ' (7일 · 월~일)')],
        ['입고 기한', fcIsLive()
          ? esc(dstr(CUR.end) + '까지 게시 · 수수료는 접수 후 입금')
          : esc(dfmt(FC_DELIVER.date) + ' ' + FC_DELIVER.time + '까지 협회 입고 (미입고 시 자동 취소)')],
        ['설치 방식', fcIsLive()
          ? (applicantKind() === 'agency' ? '협회 검인 후 <b>광고사 직접 설치</b>' : '협회 검인 후 <b>광고사 의뢰</b> (일반인 직접설치 금지)')
          : '협회 일괄 게첨 (당첨분은 목요일 확정 → 월요일 게첨)'],
        ['등록증 사본', applicantKind() === 'agency' ? '광고대행사 — 가입 때 제출한 등록증으로 갈음' : (v.license ? esc(v.license) : '미첨부')]
      ];
      $('#fcSummary').innerHTML = '<dl>' + rows.map(function (r) {
        return '<dt>' + r[0] + '</dt><dd>' + r[1] + '</dd>';
      }).join('') + '</dl>';
    }
    if ($('#fcFeeTotal')) $('#fcFeeTotal').textContent = won(f.total);
    if ($('#fcFeeLines')) {
      $('#fcFeeLines').innerHTML =
        '<span><em style="font-style:normal">' + esc(feeUnitText()) + '</em></span>' +
        '<span>계산 내역 <b>' + esc(feeText(f)) + '</b></span>' +
        '<span>1주(7일) 기준 · 접수 후 입금 (미입금·미입고 시 자동 취소)</span>';
    }
    if ($('#fcInstallInfo')) {
      var kind = applicantKind();
      $('#fcInstallInfo').innerHTML = (fcIsLive() || holidayDirectInstallOn(ui.fcWeek))
        ? '<div class="callout warn">' + IC.alert + '<div>' + directInstallHTMLOf(kind) + '</div></div>'
        : '<div class="callout info">' + IC.info + '<div>목요일 선착순으로 확정된 매는 <b>' + dfmt(FC_DELIVER.date) + ' ' + FC_DELIVER.time +
          '까지 협회에 입고</b>해야 하며, 미입고 시 자동 취소(반려)되고 <b>차기 1개 주 회차 접수 제한</b>이 적용됩니다.</div></div>';
    }
  }

  function renderFcFoot() {
    var n = ui.fcStep || 1;
    if ($('#fcPrev')) $('#fcPrev').style.visibility = n === 1 ? 'hidden' : 'visible';
    if ($('#fcNext')) $('#fcNext').innerHTML = n === 4
      ? '접수 제출' + IC.check
      : '다음 단계<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M10 6l6 6-6 6"/></svg>';
    if ($('#fcStepHint')) $('#fcStepHint').textContent = FC_STEP_HINT[n - 1] || '';
  }

  function fcSetStep(n) {
    var was = ui.fcStep || 1;
    n = Math.max(1, Math.min(4, Number(n) || 1));
    ui.fcStep = n;
    $$('#fcStepper .step').forEach(function (s) {
      var k = Number(s.getAttribute('data-step'));
      s.classList.toggle('active', k === n);
      s.classList.toggle('done', k < n);
      var num = s.querySelector('.num');
      if (num) num.innerHTML = k < n ? '✓' : String(k);
    });
    $$('#fcForm .step-body').forEach(function (b) { b.classList.toggle('active', b.id === 'fcStep' + n); });
    renderFcStep2(); renderFcStep3(); renderFcStep4(); renderFcFoot();
    if (was !== n) scrollTopSmooth();
    return n;
  }

  function fcSetQty(n) {
    var mx = fcMaxQty();
    n = Number(n) || 0;
    if (n < QTY_MIN) n = QTY_MIN;
    if (mx && n > mx) { n = mx; toast('지금 남은 잔여 매수는 ' + mx + '매입니다 — ' + mx + '매로 맞췄습니다.', true); }
    ui.fcQty = n;
    if (fcPicks().length > n) ui.fcPicks = fcPicks().slice(0, n);
    renderFirst();
    return n;
  }

  /* 3단계 담기/해제 */
  function fcTogglePick(pid) {
    var p = placementById(pid);
    if (!p) return false;
    var arr = fcPicks(), i = arr.indexOf(pid);
    if (i >= 0) { arr.splice(i, 1); toast(p.name + ' — 3단계 선택을 해제했습니다.'); renderFirst(); return true; }
    var max = fcQtyNow();
    if (arr.length >= max) {
      toast('이미 ' + max + '개소를 담았습니다 — 2단계 신청 수량(' + max + '매)만큼만 고를 수 있습니다. 수량을 늘리려면 2단계로 돌아가세요.', true);
      return false;
    }
    var yTxt = String(($('#fcAdvertiser') ? $('#fcAdvertiser').value : '') || '') + ' ' + String(($('#fcText') ? $('#fcText').value : '') || '');
    if (p.youthProtect && youthHitOf(yTxt)) {
      toast('🚸 청소년유해광고 감지 — ' + p.name + '은(는) 학교·유치원 초인접 게시대라 담을 수 없습니다.', true);
      return false;
    }
    var mb = makerBlockOf(pid, currentMakerInfo());
    if (mb) { toast(p.name + ' — 제작업체 금지 게시대입니다. ' + (mb.block.reason ? '(' + mb.block.reason + ')' : ''), true); return false; }
    if (placeBlocked(p) || !fcLeftOf(p)) { toast(p.name + ' — 지금은 담을 수 없는 게시대입니다.' + (p.broken ? ' (고장·수리중)' : ''), true); return false; }
    /* 미배정 상시접수(remain.html)는 근접 게시대 동시 담기 허용 — 주간 추첨/취소분 선착순만 택1 제한 */
    var adj = (PAGE === 'remain') ? [] : adjRankConflicts(arr.concat([pid]));
    if (adj.length) {
      toast('택1 제한 — ' + adj[0].no + ' 구역의 ' + adj[0].a.name + '·' + adj[0].b.name + '은(는) 한 접수에 함께 담을 수 없습니다.', true);
      return false;
    }
    arr.push(pid);
    toast(p.name + ' — 3단계에 담았습니다. (' + arr.length + '/' + max + ')');
    renderFirst();
    return true;
  }

  /* 시안 파일 첨부 — JPG·PNG / 5MB 이하 (김재봉 님 지시로 시안 첨부는 필수) */
  function fcHandleFile(file) {
    if (!file) return false;
    var okType = /^image\//.test(String(file.type || '')) || /\.(png|jpe?g|gif|webp)$/i.test(String(file.name || ''));
    if (!okType) { toast('시안 파일은 이미지(JPG·PNG)만 첨부할 수 있습니다.', true); return false; }
    if (file.size && file.size > 5 * 1024 * 1024) { toast('시안 파일은 5MB 이하만 첨부할 수 있습니다.', true); return false; }
    ui.fcFile = { name: file.name, size: file.size || 0 };
    ui.fcFilePreview = null; ui.fcDesignTone = null; ui.fcDesignExtracted = null;
    if ($('#fcFilePreview')) {
      $('#fcFilePreview').innerHTML = '<div class="drop-preview"><div class="fi"><b>' + esc(file.name) + '</b><span>' +
        Math.max(1, Math.round((file.size || 0) / 1024)) + 'KB · 시안 파일</span></div></div>';
    }
    if ($('#fcFDesign')) $('#fcFDesign').classList.remove('invalid');
    try {
      var rd = new FileReader();
      rd.onload = function () {
        ui.fcFilePreview = String(rd.result || '');
        var info = extractDesignInfo(file.name, ui.fcFilePreview);
        ui.fcDesignExtracted = info;
        applyDesignAutofill('fc', info);
        renderFcFilePreview();
        analyzeDesignTone(ui.fcFilePreview, function (tone) { ui.fcDesignTone = tone; renderFcFilePreview(); });
        runDesignOcr('fc', file.name, ui.fcFilePreview);
      };
      rd.readAsDataURL(file);
    } catch (e) { }
    toast('시안 파일을 첨부했습니다 — ' + file.name);
    return true;
  }

  function readFc() {
    var m = currentMember();
    var adv = String(($('#fcAdvertiser') ? $('#fcAdvertiser').value : '') || '').trim();
    var biz = String(($('#fcAdvBiz') ? $('#fcAdvBiz').value : '') || '').trim();
    var ph = String(($('#fcAdvPhone') ? $('#fcAdvPhone').value : '') || '').trim();
    return {
      advertiser: adv, advertiserBiz: biz, advertiserPhone: ph,
      text: String(($('#fcText') ? $('#fcText').value : '') || '').trim(),
      qty: fcQtyVal() || fcQtyNow(),
      company: m ? m.company : adv,
      owner: m ? m.owner : adv,
      phone: m ? (m.phone || '') : (ph || '010-0000-0000'),
      memberId: m ? m.id : null,
      kind: applicantKind(),
      license: fcLicState().name || '',
      licenseNo: fcLicState().no || '',
      file: ui.fcFile || null
    };
  }

  function fcErr(sel) { var f = $(sel); if (f && f.classList) f.classList.add('invalid'); }

  function validateFcStep(n) {
    clearErrs();
    var v = readFc();
    if (n === 1) {
      var ok = true;
      if (!v.advertiser) { fcErr('#fcFAdv'); ok = false; }
      if (v.advertiserBiz && normDigits(v.advertiserBiz).length !== 10) {
        fcErr('#fcFAdvBiz');
        var e1 = $('#fcFAdvBiz') ? $('#fcFAdvBiz').querySelector('.err-txt') : null;
        if (e1) e1.textContent = '사업자등록번호는 숫자 10자리로 입력해 주세요.';
        ok = false;
      }
      if (v.advertiserPhone && !/^0\d{1,2}[- ]?\d{3,4}[- ]?\d{4}$/.test(String(v.advertiserPhone).replace(/\s/g, ''))) { fcErr('#fcFAdvPhone'); ok = false; }
      if (String(v.text || '').length < 4) { fcErr('#fcFText'); ok = false; }
      var fcAb = checkAbusiveText((v.advertiser || '') + ' ' + (v.text || ''));
      if (fcAb.bad) {
        syncFcAbuseNote(); fcErr('#fcFText');
        toast(fcAb.marriage.length ? '결혼중개업법 위반·인권침해(매매혼·성상품화) 우려 표현이 포함되어 접수할 수 없습니다.' : '비방·욕설·미풍양속 저해 문구가 포함되어 접수할 수 없습니다.', true);
        return false;
      }
      if (!v.file) {
        fcErr('#fcFDesign');
        toast('현수막 시안 파일 첨부가 필수입니다 — 시안을 첨부하거나 [시연용 샘플 시안 첨부]를 눌러 주세요.', true);
        return false;
      }
      if (v.kind !== 'agency' && !String(v.license || '').trim()) {
        fcErr('#fcLicBox');
        toast('일반업체·비회원은 현수막을 출력·설치할 광고사의 옥외광고업 등록증 사본을 첨부해야 합니다.', true);
        return false;
      }
      if (!ok) { toast('입력하지 않았거나 형식이 맞지 않는 항목이 있습니다.', true); return false; }
      /* 페널티(접수 제한) · 실제 광고주 단위 중복 접수 — 주간 추첨 접수와 같은 기준 */
      var pen = activePenaltyFor({ name: v.advertiser, biz: v.advertiserBiz, phone: v.advertiserPhone });
      if (pen) {
        fcErr('#fcFAdv');
        toast(v.advertiser + ' 님은 페널티로 ' + penaltyRoundsTxt(pen) + ' 접수 제한 중입니다. (사유: ' + pen.reason + ' · ' + penaltyReleaseTxt(pen) + ')', true);
        return false;
      }
      var wk = fcIsLive() ? CUR.start : ROUND.postStart, dupHit = null;
      db.apps.forEach(function (a) {
        if (!a || weekStartOf(a.start || ROUND.postStart) !== wk || a.status === '반려') return;
        if (sameAdvertiser(advOfApp(a), { name: v.advertiser, biz: v.advertiserBiz, phone: v.advertiserPhone })) dupHit = a;
      });
      if (dupHit) {
        fcErr('#fcFAdv');
        toast('같은 실제 광고주(' + v.advertiser + ')로 이미 이번 회차에 ' + dupHit.id + ' 건이 접수되어 있습니다. 광고주 1곳당 1건만 접수됩니다.', true);
        return false;
      }
      if (!$('#fcChkRule') || !$('#fcChkRule').checked || !$('#fcChkDup') || !$('#fcChkDup').checked) {
        toast('필수 확인 항목에 동의해 주세요.', true);
        var fa1 = $('#fcAgree1'), fa2 = $('#fcAgree2');
        var frOk = !!($('#fcChkRule') && $('#fcChkRule').checked);
        var fdOk = !!($('#fcChkDup') && $('#fcChkDup').checked);
        if (fa1) {
          fa1.style.borderColor = frOk ? '' : '#e9a8a8';
          fa1.classList.remove('invalid');
          if (!frOk) { void fa1.offsetWidth; fa1.classList.add('invalid'); }
        }
        if (fa2) {
          fa2.style.borderColor = fdOk ? '' : '#e9a8a8';
          fa2.classList.remove('invalid');
          if (!fdOk) { void fa2.offsetWidth; fa2.classList.add('invalid'); }
        }
        var fcBad = !frOk ? fa1 : fa2;
        if (fcBad && fcBad.scrollIntoView) {
          fcBad.scrollIntoView({ behavior: 'smooth', block: 'center' });
          var finp = fcBad.querySelector('input');
          if (finp && finp.focus) { try { finp.focus({ preventScroll: true }); } catch (e) { finp.focus(); } }
        }
        return false;
      }
      if ($('#fcAgree1')) { $('#fcAgree1').style.borderColor = ''; $('#fcAgree1').classList.remove('invalid'); }
      if ($('#fcAgree2')) { $('#fcAgree2').style.borderColor = ''; $('#fcAgree2').classList.remove('invalid'); }
      return true;
    }
    if (n === 2) {
      var st = fcSessionState();
      if (!st.open) { toast(st.msg, true); return false; }
      var q = v.qty, mx = fcMaxQty();
      if (!q || q < QTY_MIN) { fcErr('#fcFQty'); toast('신청 수량을 1매 이상 입력해 주세요.', true); return false; }
      if (q > QTY_MAX) { fcErr('#fcFQty'); toast('1회 최대 접수 수량은 50매까지입니다.', true); return false; }
      if (!mx) { fcErr('#fcFQty'); toast('지금 이 창구에 남은 잔여 매수가 없습니다 — 다른 창구를 골라 주세요.', true); return false; }
      if (q > mx) { fcErr('#fcFQty'); toast('지금 남은 잔여 매수는 ' + mx + '매입니다 — 신청 수량을 ' + mx + '매 이하로 줄여 주세요.', true); return false; }
      return true;
    }
    if (n === 3) {
      var q2 = v.qty, picks = fcPicks();
      if (!q2 || q2 < QTY_MIN || q2 > QTY_MAX) { toast('2단계에서 신청 수량(1~50매)을 다시 확인해 주세요.', true); return false; }
      if (picks.length !== q2) {
        toast('신청 수량 ' + q2 + '매만큼 서로 다른 게시대 ' + q2 + '개소를 담아야 합니다. (현재 ' + picks.length + '개소)', true);
        return false;
      }
      var bad = null;
      picks.forEach(function (pid) {
        if (bad) return;
        var p = placementById(pid);
        if (!p) { bad = { name: String(pid), why: '없는 게시대입니다.' }; return; }
        if (!fcBoardOk(p)) { bad = { name: p.name, why: '정치행정(공문 전용) 게시대는 미배정 선착순에서 접수할 수 없습니다.' }; return; }
        if (placeBlocked(p)) { bad = { name: p.name, why: '고장·수리중이거나 전체 풀가림입니다.' }; return; }
        if (fcLeftOf(p) <= 0) { bad = { name: p.name, why: '잔여 면이 없습니다.' }; return; }
        var mb = makerBlockOf(pid, currentMakerInfo());
        if (mb) bad = { name: p.name, why: '제작업체 금지 게시대입니다.' };
      });
      if (bad) { toast(bad.name + ' — ' + bad.why + ' 다른 게시대를 골라 주세요.', true); return false; }
      var adj = adjRankConflicts(picks);
      if (adj.length) {
        toast('택1 제한 — ' + adj[0].no + ' 구역의 ' + adj[0].a.name + '·' + adj[0].b.name + '이(가) 함께 담겨 있습니다. 한 곳을 해제해 주세요.', true);
        return false;
      }
      return true;
    }
    return true;
  }

  function fcNextStep() {
    if (!currentMember() && !ui.guestAck) {
      ui.pendingAdvance = 'fcnext';
      if (maybeAskGuest()) { toast('로그인·회원가입 또는 비회원으로 계속을 골라 주세요.', true); return false; }
    }
    if ((ui.fcStep || 1) >= 4) return !!fcSubmit();
    if (!validateFcStep(ui.fcStep || 1)) { focusFirstInvalid(); return false; }
    fcSetStep((ui.fcStep || 1) + 1);
    return true;
  }

  function fcSubmit() {
    if (!validateFcStep(1)) { fcSetStep(1); focusFirstInvalid(); return null; }
    if (!validateFcStep(2)) { fcSetStep(2); focusFirstInvalid(); return null; }
    if (!validateFcStep(3)) { fcSetStep(3); focusFirstInvalid(); return null; }
    var v = readFc(), picks = fcPicks().slice();
    if (!picks.length) { toast('3단계에서 게시대를 담아 주세요.', true); return null; }
    var live = fcIsLive(), m = currentMember();
    var wkStart = live ? (fcIsLive() ? fcWeek() : CUR.start) : ROUND.postStart;
    var assigned = picks.map(function (pid) {
      var p = placementById(pid);
      var slot = live ? (slotPlan(p.id, wkStart).free[0] || '') : fcSlotOf(p);
      return { pid: pid, qty: 1, slot: slot };
    });
    var isCurWeek = live && weekStartOf(wkStart) === weekStartOf(CUR.start);
    var id = nextAppId((live ? (isCurWeek ? CUR.id : weekRoundId(wkStart)) : ROUND.id) + (live ? '-L-' : '-C-'));
    db.seq += 1;
    var app = {
      id: id, round: live ? (isCurWeek ? CUR.id : weekRoundId(wkStart)) : ROUND.id, week: wkStart,
      company: v.company, owner: v.owner, phone: v.phone,
      memberId: m ? m.id : null,
      appType: v.kind === 'agency' ? 'agency' : 'direct',
      advertiser: v.advertiser, advertiserBiz: v.advertiserBiz, advertiserPhone: v.advertiserPhone,
      qty: v.qty, awardedQty: v.qty,
      placements: picks.slice(), assignedPlaces: assigned,
      priority1: picks.slice(), priority2: [], priority3: [], designatedOnly: false,
      p1: picks[0] || '', p2: '', p3: '',
      eco: true, status: live ? (isCurWeek ? '게시중' : '선착순확정') : '선착순확정',
      text: v.text, appliedAt: nowStamp(), start: wkStart, days: 7,
      file: v.file ? v.file.name : null, preview: ui.fcFilePreview || null,
      license: v.license || '', licenseNo: v.licenseNo || '',
      mine: true, paid: false, firstCome: !live,
      designTone: ui.fcDesignTone || null,
      liveWeek: isCurWeek, directInstall: live || holidayDirectInstallOn(ui.fcWeek), installType: v.kind,
      directInstallMsg: live ? liveMsgOf(v.kind) : (holidayDirectInstallOn(ui.fcWeek) ? holidayInstallMsg(v.kind) : ''),
      delivered: false,
      deliveryDue: isCurWeek ? (CUR.end + ' 18:00') : (FC_DELIVER.date + ' ' + FC_DELIVER.time),
      assignedTo: picks[0] || null, rank: null, reject: null, drawId: null
    };
    db.apps.push(app);
    picks.forEach(function (pid) {
      var p = placementById(pid);
      if (!p) return;
      if (ui.fcCover && ui.fcCover[pid]) delete ui.fcCover[pid];
      /* 목요일 선착순분은 잔여 면(inUse)을 직접 차감하고, 진행 중 주간은 그 주 슬롯 계산에 그대로 반영된다 */
      if (!live) {
        if (reclaimedOf(p) > 0) db.reclaimed[p.id] = reclaimedOf(p) - 1;
        else p.inUse = Math.min(p.cap, p.inUse + 1);
      }
    });
    audit(live ? '진행주간' : '선착순', id + ' ' + placeNamesTxt(picks, 3) + ' ' + v.qty + '매 접수 확정 (광고주 ' + v.advertiser + ' · ' +
      (live ? '진행 중 주간 ' + dstr(CUR.start) + '~' + dstr(CUR.end) + ' · ' + (v.kind === 'agency' ? '광고사 직접 설치' : '광고사 의뢰 · 일반인 직접설치 금지')
        : ROUND.label + ' 목요일 선착순') + ')');
    save();
    fcReset();
    renderFirst(); renderStatus(); renderMypage();
    showFcDone(app);
    return app;
  }

  function fcReset() {
    ui.fcStep = 1;
    ui.fcQty = QTY_MIN;
    ui.fcPicks = [];
    ui.fcFile = null;
    ui.fcFilePreview = null;
    ui.fcLic = { name: '', no: '', src: '', fail: false };
    ['#fcAdvertiser', '#fcAdvBiz', '#fcAdvPhone', '#fcText'].forEach(function (s) { var el = $(s); if (el) el.value = ''; });
    ['#fcChkRule', '#fcChkDup'].forEach(function (s) { var el = $(s); if (el) el.checked = false; });
    if ($('#fcTextCount')) $('#fcTextCount').textContent = '0';
    if ($('#fcDesign')) { try { $('#fcDesign').value = ''; } catch (e) { } }
    if ($('#fcFilePreview')) $('#fcFilePreview').innerHTML = '';
    clearErrs();
    renderFcLic();
    renderFirst();
    return true;
  }

  /* 접수 완료 — 다음 건 접수는 화면 맨 위(1단계)로 */
  function showFcDone(app) {
    var live = !!app.liveWeek;
    var kind = applicantKind();
    var body = '<div class="callout ok">' + IC.check +
      '<div><b>' + (live ? '진행 중 주간 잔여석 접수' : '목요일 잔여석 선착순 접수') + '가 완료되었습니다.</b><br>' +
      esc(placeNamesTxt(app.placements || [], 4)) + ' · <b>' + qtyOf(app) + '매</b> · 게시 기간 <b>' + dstr(app.start) + ' ~ ' + dstr(addDays(app.start, 6)) +
      '</b> · 접수번호 <b>' + esc(app.id) + '</b></div></div>' +
      (live
        ? '<div class="callout warn" style="margin-bottom:6px">' + IC.alert + '<div>' + liveMsgHTMLOf(kind) + '</div></div>'
        : '<div class="callout info" style="margin-bottom:6px">' + IC.info + '<div>현수막 실물은 <b>' + dfmt(FC_DELIVER.date) + ' ' + FC_DELIVER.time + '까지</b> 협회로 입고해 주세요. 미입고 시 자동 취소(반려)됩니다.</div></div>') +
      '<div class="hint-txt">수수료 <b>' + won(feeFor(qtyOf(app), 7).total) + '</b>은 접수 후 입금해 주세요. 마이페이지에서 접수 내역과 게시 지정서를 확인하실 수 있습니다.</div>';
    openModal({
      title: '접수 완료 — ' + (live ? '진행 중 주간 잔여석' : '목요일 선착순'),
      sub: app.id + ' · ' + (app.advertiser || ''),
      body: body,
      foot: '<button class="btn ghost" id="btnFcDone" type="button">닫기 (다음 건 접수)</button>' +
        '<button class="btn" id="btnFcReceipt" type="button">접수증 보기</button>' +
        '<button class="btn primary" id="btnFcMypage" type="button">마이페이지에서 보기</button>',
      after: function () {
        onEl('#btnFcMypage', 'click', function () { closeModal(); goPage('mypage.html'); });
        onEl('#btnFcDone', 'click', function () { closeModal(); fcReset(); renderFirst(); scrollTopSmooth(); });
        onEl('#btnFcReceipt', 'click', function () { closeModal(); showReceiptModal(app, false); });
      }
    });
    return app;
  }

  /* ── first.html 접수창(목요일 선착순·진행 주간 잔여석) — 등록증 사본 분기 ─────
     (2026-11-23 김재봉 님 지시 "광고대행사 접수 시 등록증 제출 삭제, 일반인은 등록증 요청")
     · 광고대행사 → 칸 없음 (회원가입 때 1회 제출로 갈음)
     · 일반업체·비회원 → 광고사(출력·설치 업체) 등록증 사본 필수 · 첨부하면 등록번호 자동 추출 */
  /* ── first.html 접수창(목요일 선착순·진행 주간 잔여석) — 등록증 사본 분기 ─────
     (2026-11-23 김재봉 님 지시 "광고대행사 접수 시 등록증 제출 삭제, 일반인은 등록증 요청")
     · 광고대행사 → 칸 없음 (회원가입 때 1회 제출로 갈음)
     · 일반업체·비회원 → 광고사(출력·설치 업체) 등록증 사본 필수 · 첨부하면 등록번호 자동 추출 */
  function fcLicState() {
    if (!ui.fcLic || typeof ui.fcLic !== 'object') ui.fcLic = { name: '', no: '', src: '', fail: false };
    return ui.fcLic;
  }
  function fcLicBoxHTML() {
    return '<div class="field" id="fcLicBox" style="margin-top:12px">' +
      '<label for="fcLic">옥외광고업 등록증 사본 첨부<span class="req">*</span></label>' +
      '<div class="hint-txt">일반인은 직접 설치가 금지되어 있어 <b>광고사(옥외광고업 등록업체)에 의뢰</b>해야 합니다. 그 광고사의 <b>등록증 사본</b>을 첨부해 주세요 — 첨부하면 <b>등록번호가 자동 추출</b>됩니다.</div>' +
      '<div class="dz-wrap" style="margin-top:6px"><div class="dz-tools" style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">' +
      '<input type="file" id="fcLic" accept="image/*,application/pdf,.txt">' +
      '<button class="btn sm ghost" id="btnFcLicSample" type="button">샘플 등록증 첨부</button></div></div>' +
      '<div class="hint-txt" id="fcLicName">첨부된 파일이 없습니다.</div>' +
      '<div class="lic-extract hidden" id="fcLicExtract"></div></div>';
  }
  function renderFcLic() {
    var st = fcLicState();
    var nEl = $('#fcLicName'), bx = $('#fcLicExtract');
    if (nEl) nEl.innerHTML = st.name ? '첨부됨 · <b>' + esc(st.name) + '</b>' : '첨부된 파일이 없습니다.';
    if (bx) {
      if (!st.name) { bx.className = 'lic-extract hidden'; bx.innerHTML = ''; }
      else if (st.no) {
        bx.className = 'lic-extract';
        bx.innerHTML = '<span>🏷️ 등록번호 자동 추출</span><b>' + esc(st.no) + '</b><span class="sm">' +
          esc(st.src || '') + ' · 접수 데이터에 함께 저장됩니다.</span>';
      } else {
        bx.className = 'lic-extract fail';
        bx.innerHTML = '<span>🏷️ 등록번호 자동 추출 실패</span><b>등록번호를 직접 확인해 주세요</b>';
      }
    }
  }
  function fcLicAttach(name, no, src) {
    ui.fcLic = { name: String(name || ''), no: String(no || ''), src: String(src || ''), fail: !no };
    renderFcLic();
    return ui.fcLic;
  }
  function bindFcLic() {
    var f = $('#fcLic');
    if (f) onEl('#fcLic', 'change', function (e) {
      var file = e.target && e.target.files && e.target.files[0];
      if (!file) return;
      ui.fcLic = { name: file.name, no: extractRegNo(file.name), src: file.name, fail: false };
      renderFcLic();
      scanFileRegNo(file, function (no, src) {
        if (!fcLicState().name) return;
        ui.fcLic.no = no || ''; ui.fcLic.src = src || ui.fcLic.name;
        renderFcLic();
      });
    });
    if ($('#btnFcLicSample')) onEl('#btnFcLicSample', 'click', function () {
      fcLicAttach('옥외광고업등록증_샘플.pdf', '충남서산-제2024-0012호', '시연용 샘플 등록증');
      toast('샘플 등록증 사본을 첨부했습니다 — 등록번호 충남서산-제2024-0012호 자동 추출.');
    });
  }

  /* 목요일 선착순 배정 자리 — 풀가림을 직접 고른 경우 그 칸, 아니면 정상 칸부터 */
  function fcSlotOf(p) {
    var plan = slotPlan(p.id);
    var picked = (ui.fcCover && ui.fcCover[p.id]) || '';
    if (picked && plan.free.indexOf(picked) >= 0) return picked;
    var normal = plan.free.filter(function (c) { return !slotIsCover(p, c) && !slotOtherOf(p, c); });
    return (normal[0] || plan.free[0] || '');
  }
  /* ── 풀가림 자리 선택 — 목요일 선착순 전용 안내·확인 팝업 (김재봉 님 지시 2026-11-22) ──
     · 풀가림 단수는 정기 추첨 접수에서 제외되고 목요일 잔여석 선착순에서만 선택할 수 있습니다.
     · 선택하면 가로수·잡초 등으로 시야가 가려질 수 있다는 안내를 확인한 것으로 봅니다. */
  function askFcCover(pid) {
    var p = placementById(pid);
    if (!p) return false;
    var st = fcSessionState();
    if (!st.open) { toast(st.msg, true); return false; }
    var plan = slotPlan(p.id, fcIsLive() ? CUR.start : ROUND.postStart);
    var covers = plan.free.filter(function (c) { return slotIsCover(p, c); });
    var others = plan.free.filter(function (c) { var o = slotOtherOf(p, c); return !!o && o.mode === 'warn'; });
    var seats = covers.map(function (c) { return { code: c, kind: 'cover', text: '가로수·잡초·구조물 등으로 현수막 일부가 가려질 수 있는 자리' }; })
      .concat(others.map(function (c) { var o = slotOtherOf(p, c); return { code: c, kind: 'other', text: o.text }; }));
    if (!seats.length) { toast(p.name + ' — 지금 풀가림·기타사유로 남은 자리가 없습니다.', true); return false; }
    if (!ui.fcCover) ui.fcCover = {};
    openModal({
      title: '⚠️ 풀가림·기타사유 안내 — 목요일 선착순', sub: p.name + ' · ' + seats.length + '면',
      body: '<div class="callout warn">' + IC.alert + '<div><b>풀가림</b>은 가로수·잡초 등으로 현수막 일부가 가려질 수 있는 자리이고, <b>기타사유</b>는 관리자가 안내를 등록한 자리입니다. 두 자리 모두 <b>정기 추첨 접수에서는 제외</b>되고 <b>목요일 잔여석 선착순</b>에서만 선택할 수 있습니다.</div></div>' +
        '<div class="hint-txt" style="margin:10px 0 6px">접수할 자리를 고르세요. 선택하면 위 안내와 사유를 확인한 것으로 봅니다.</div>' +
        '<div class="fc-cover-list">' + seats.map(function (s2, i) {
          return '<label class="check"><input type="radio" name="fcCoverSlot" value="' + esc(s2.code) + '"' + (i === 0 ? ' checked' : '') + '> <span><b>' +
            esc(slotName(p, s2.code)) + '</b> <span class="sm">(' + esc(s2.code) + ' · ' + (s2.kind === 'cover' ? '풀가림' : '기타사유') + ')</span>' +
            '<span class="sm" style="display:block">' + esc(s2.text) + '</span></span></label>';
        }).join('') + '</div>',
      foot: '<button class="btn ghost" data-close type="button">취소</button>' +
        '<button class="btn primary" id="btnFcCoverGo" type="button">확인하고 예약</button>',
      after: function () {
        onEl('#btnFcCoverGo', 'click', function () {
          var sel = document.querySelector('input[name="fcCoverSlot"]:checked');
          var code = sel ? String(sel.value) : seats[0].code;
          ui.fcCover[p.id] = code;
          closeModal();
          toast(p.name + ' ' + slotName(p, code) + ' — 안내를 확인했습니다. 접수를 진행합니다.');
          fcTogglePick(p.id);
        });
      }
    });
    return true;
  }

  function doBookFirst(id, adv) {
    var p = placementById(id);
    var st = firstComeState();
    if (placeBlocked(p) || !st.open || fcAvailOf(p) <= 0) { toast('지금은 잔여석 접수 시간이 아니거나 고장·풀가림 게시대입니다.', true); return null; }
    adv = adv || { name: '재봉기획', biz: '', phone: '010-0000-0000' };
    var pen = activePenaltyFor(adv);
    if (pen) {
      toast(adv.name + ' 님은 페널티로 ' + penaltyRoundsTxt(pen) + ' 접수 제한 중입니다. (사유: ' + pen.reason + ' · ' + penaltyReleaseTxt(pen) + ')', true);
      return null;
    }
    /* 인접 게시대 택1 — 목요일 취소분 선착순(first.html)은 차단,
       미배정 상시접수(remain.html)는 근접 게시대 동시 접수 허용 (2026-11-23 김재봉 님 지시) */
    var adjBlk = (PAGE === 'remain') ? null : adjFirstComeBlock(adv, id);
    if (adjBlk) {
      toast('택1 제한 — 이번 회차에 ' + adjBlk.name + '이(가) 확정되어 ' + adjBlk.no + ' 구역의 두 게시대를 함께 신청할 수 없습니다. ' + p.name + '은(는) 예약할 수 없습니다.', true);
      return null;
    }
    var app = {
      id: nextAppId(ROUND.id + '-C-'), round: ROUND.id, company: '재봉기획',
      owner: '김재봉', phone: '010-0000-0000',
      appType: 'agency', advertiser: adv.name, advertiserBiz: adv.biz || '', advertiserPhone: adv.phone || '010-0000-0000',
      license: adv.license || '', licenseNo: adv.licenseNo || '',
      qty: 1, awardedQty: 1, placements: [p.id], assignedPlaces: [{ pid: p.id, qty: 1, slot: fcSlotOf(p) }],
      priority1: [p.id], priority2: [], priority3: [], designatedOnly: false,
      p1: p.id, p2: '', p3: '',
      eco: true, status: '선착순확정', text: '선착순 예약 (문구는 사무국 확인)',
      appliedAt: nowStamp(), start: ROUND.postStart, days: 7,
      file: null, preview: null, mine: true, paid: false, firstCome: true,
      delivered: false, deliveryDue: FC_DELIVER.date + ' ' + FC_DELIVER.time,
      assignedTo: p.id, rank: null, reject: null, drawId: null
    };
    db.seq += 1;
    db.apps.push(app);
    if (ui.fcCover && ui.fcCover[p.id]) delete ui.fcCover[p.id];
    if (reclaimedOf(p) > 0) db.reclaimed[p.id] = reclaimedOf(p) - 1;
    else p.inUse = Math.min(p.cap, p.inUse + 1);
    audit('선착순', app.id + ' ' + p.name + ' 1매 예약 확정 (광고주 ' + adv.name + ' · 목요일 선착순 접수)');
    save();
    renderFirst(); renderStatus(); renderMypage();
    var slotNow = (app.assignedPlaces[0] && app.assignedPlaces[0].slot) || '';
    toast(p.name + (slotNow ? ' ' + slotNow : '') + ' 1매가 예약 확정되었습니다. ' + dfmt(ROUND.deliverBy) + ' ' + ROUND.deliverTime + '까지 입금·입고해 주세요.');
    return app;
  }
  function doBookLive(id, adv) {
    var p = placementById(id);
    var st = liveWeekState();
    if (!p || p.broken || !st.open || liveAvailOf(p) <= 0) {
      toast('지금은 진행 중 주간 잔여석을 접수할 수 없거나 마감된 게시대입니다.', true);
      return null;
    }
    adv = adv || {};
    var kind = adv.kind === 'agency' ? 'agency' : 'general';
    var name = String(adv.name || '').trim() || '재봉기획';
    var biz = String(adv.biz || '').trim();
    var pen = activePenaltyFor({ name: name, biz: biz, phone: '' });
    if (pen) {
      toast(name + ' 님은 페널티로 ' + penaltyRoundsTxt(pen) + ' 접수 제한 중입니다. (사유: ' + pen.reason + ' · ' + penaltyReleaseTxt(pen) + ')', true);
      return null;
    }
    var plan = slotPlan(p.id, CUR.start);
    var slot = plan.free[0] || '';
    var m = currentMember();
    var msg = liveMsgOf(kind);
    var app = {
      id: nextAppId(CUR.id + '-L-'), round: CUR.id, week: CUR.start,
      company: m ? m.company : (kind === 'agency' ? name : '비회원 (게스트)'),
      owner: m ? m.owner : name, phone: m ? (m.phone || '010-0000-0000') : '010-0000-0000',
      appType: kind === 'agency' ? 'agency' : 'direct',
      advertiser: name, advertiserBiz: biz, advertiserPhone: m ? (m.phone || '') : '',
      memberId: m ? m.id : '',
      qty: 1, awardedQty: 1, placements: [p.id], assignedPlaces: [{ pid: p.id, qty: 1, slot: slot }],
      priority1: [p.id], priority2: [], priority3: [], designatedOnly: false,
      p1: p.id, p2: '', p3: '',
      eco: true, status: '게시중', text: '진행 중 주간 잔여석 접수 (문구는 사무국 확인)',
      appliedAt: nowStamp(), start: CUR.start, days: 7,
      file: null, preview: null, mine: true, paid: false, firstCome: false,
      liveWeek: true, directInstall: true, installType: kind, directInstallMsg: msg,
      license: adv.license || '', licenseNo: adv.licenseNo || '',
      delivered: false, deliveryDue: CUR.end + ' 18:00',
      assignedTo: p.id, rank: null, reject: null, drawId: null
    };
    db.seq += 1;
    db.apps.push(app);
    audit('진행주간', app.id + ' ' + p.name + ' 1매 접수 확정 (광고주 ' + name + ' · 진행 중 주간 ' + dstr(CUR.start) + '~' + dstr(CUR.end) + ' · ' +
      (kind === 'agency' ? '광고사 직접 설치' : '광고사 의뢰 · 일반인 직접설치 금지') + ')');
    save();
    renderFirst(); renderStatus(); renderMypage();
    return app;
  }


  /* 3단계 담기 요청 — 로그인 대기(pendingAdvance) 뒤에 이어지는 진입점 */
  function bookFirst(id) { return fcTogglePick(id); }
  function bookLive(id) { return fcTogglePick(id); }

  /* ---------------------------------------------------------------
     9. 마이페이지
     --------------------------------------------------------------- */
  var BADGE_MAP = {
    '시안심사중': ['b-blue', '시안 심사중'],
    '행사심사중': ['b-purple', '행사 심사중'],
    '정치심사중': ['b-blue', '정치행정 심사중'],
    '추첨대기': ['b-amber', '추첨 대기'],
    '입고대기': ['b-amber', '현수막 입고 대기'],
    '입고완료': ['b-green', '입고 완료 · 게시 대기'],
    '미입고취소': ['b-red', '미입고 취소(반려)'],
    '미입금취소': ['b-red', '미입금 취소'],
    '본인취소': ['b-red', '본인 사유 취소'],
    '접수취소': ['b-gray', '추첨 전 취소 (페널티 없음)'],
    '낙첨': ['b-gray', '낙첨'],
    '반려': ['b-red', '반려'],
    '게시중': ['b-navy', '게시중'],
    '게시종료': ['b-gray', '게시 종료'],
    '선착순확정': ['b-purple', '선착순 확정']
  };
  var STATUS_TXT = {
    '시안심사중': '시안 심사중',
    '행사심사중': '행사 심사 중 (승인권한자 5명 중 3명 이상 찬성 필요)',
    '정치심사중': '정치행정 심사 중 (지부장 + 감사 2인 중 1인 승인)',
    '추첨대기': '추첨 대기',
    '입고대기': '현수막 입고 대기 (수요일 18:00 마감)',
    '입고완료': '입고 완료 (게시 대기)',
    '미입고취소': '미입고 취소 (반려)',
    '미입금취소': '미입금 취소 (페널티)',
    '본인취소': '본인 사유 취소 (페널티)',
    '접수취소': '추첨 전 취소 (페널티 없음)',
    '낙첨': '낙첨',
    '반려': '반려',
    '게시중': '게시중',
    '게시종료': '게시 종료 (7일 게시 후 협회 일괄 철거)',
    '선착순확정': '선착순 확정 (입고 대기)'
  };
  function statusBadge(s) {
    var m = BADGE_MAP[s] || ['b-gray', s];
    return '<span class="badge ' + m[0] + '"><i></i>' + esc(m[1]) + '</span>';
  }

  function timelineHTML(status) {
    var steps = ['접수', '시안 심사', '전산 추첨', '현수막 입고', '게시'];
    var idxMap = { '시안심사중': 1, '행사심사중': 1, '정치심사중': 1, '반려': 1, '추첨대기': 2, '낙첨': 2, '입고대기': 3, '선착순확정': 3, '미입고취소': 3, '미입금취소': 3, '본인취소': 3, '접수취소': 1, '입고완료': 4, '게시중': 4, '게시종료': 5 };
    var now = idxMap[status];
    if (now == null) now = 0;
    return '<div class="timeline">' + steps.map(function (s, i) {
      var cls = i < now ? 'done' : (i === now ? 'now' : '');
      return '<div class="tl ' + cls + '">' + s + '</div>';
    }).join('') + '</div>';
  }

  /* ── 마이페이지 목록용 요약 카드 (김재봉 님 지시: 목록 → 클릭 → 세부 페이지) ── */
  /* ── 추첨 전 접수 취소 (페널티 없음) — 김재봉 님 지시 2026-11-23 ──────────
     · 전산 추첨이 실행되기 전(시안심사중·행사심사중·정치심사중·추첨대기) 건은
       마이페이지 목록·상세 어디서든 [❌ 접수 취소 (페널티 없음)] 버튼으로 바로 취소합니다. */
  var PRE_DRAW_STATUS = ['시안심사중', '행사심사중', '정치심사중', '추첨대기'];
  function preDrawCancelable(a) {
    return !!a && PRE_DRAW_STATUS.indexOf(a.status) >= 0 && !a.drawId && !a.awardedQty;
  }
  function preDrawCancelBtn(a, cls) {
    if (!preDrawCancelable(a)) return '';
    return '<button class="btn sm danger" data-precancel="' + esc(a.id) + '" type="button" title="추첨 전 취소는 페널티가 없습니다">❌ 접수 취소 (페널티 없음)</button>';
  }
  function preDrawCancel(id) {
    var a = findApp(id);
    if (!a || !preDrawCancelable(a)) { toast('추첨이 이미 진행되어 이 화면에서 취소할 수 없습니다.', true); return null; }
    openModal({
      title: '추첨 전 접수 취소', sub: a.id + ' · ' + (advOfApp(a).name || a.company || ''),
      body: '<div class="callout warn">' + IC.alert + '<div><b>추첨 전 접수 취소는 페널티가 부과되지 않습니다.</b> 취소하시겠습니까?<br>' +
        '<span class="sm">접수번호 ' + esc(a.id) + ' · ' + qtyOf(a) + '매 · ' + esc(placeNamesTxt(requestedPlacesOf(a), 3)) + '</span></div></div>' +
        '<div class="hint-txt">취소하면 상태가 <b>추첨 전 취소</b>로 바뀌고, 같은 회차에 다시 접수할 수 있습니다. (당첨 후·미입금·미입고 취소와 달리 <b>차기 회차 제한 없음</b>)</div>',
      foot: '<button class="btn ghost" data-close type="button">닫기</button>' +
        '<button class="btn danger" id="btnPreCancelGo" type="button">취소하고 접수 취소</button>',
      after: function () {
        onEl('#btnPreCancelGo', 'click', function () {
          a.status = '접수취소';
          a.reject = null;
          a.canceledAt = nowStamp();
          a.cancelReason = '추첨 전 접수 취소 (페널티 없음)';
          if (a.autoRepeat) { a.autoRepeat = false; a.repeatStatus = '취소'; }
          audit('접수취소', a.id + ' 추천 전 접수 취소 (페널티 없음 · ' + (advOfApp(a).name || '') + ')');
          save();
          closeModal();
          renderMypage(); renderStatus(); renderFirst(); renderAdmin();
          toast('접수가 취소되었습니다 (추첨 전 취소 · 페널티 없음)');
        });
      }
    });
    return a;
  }

  function myAppRow(a) {
    var place = placeNamesTxt(requestedPlacesOf(a), 2) || '—';
    var wrap = preDrawCancelBtn(a);
    return '<div class="mp-row-wrap">' + '<button type="button" class="mp-row" data-mppick="' + esc(a.id) + '">' +
      '<span class="mr-top"><b class="mr-no">' + esc(a.id) + '</b>' + statusBadge(a.status) + eventBadgeHTML(a) +
        (a.directInstall ? '<span class="badge b-amber"><i></i>' + esc(liveInstallLabel(liveInstallKindOf(a))) + '</span>' : '') +
        (a.designatedOnly ? '<span class="badge b-purple"><i></i>위치지정</span>' : '') + '</span>' +
      '<span class="mr-main">' + esc(advOfApp(a).name || a.company || '—') + ' — "' + esc(a.text || '') + '"</span>' +
      '<span class="mr-sub">' + qtyOf(a) + '매 · ' + esc(place) + ' · 게첨 ' + esc(weekRangeTxt(weekStartOf(a.start || ROUND.postStart))) + ' · 접수 ' + esc(a.appliedAt || '—') +
        (photosForApp(a).length ? ' · 📸 게첨사진 ' + photosForApp(a).length + '장' : '') + '</span>' +
      '<span class="mr-go">상세 보기 ›</span></button>' +
      (wrap ? '<div class="mp-row-actions">' + wrap + '</div>' : '') + '</div>';
  }
  /* ── 마이페이지 세부 페이지 (1건 전체 상세 · 목록으로 돌아가기) ── */
  function myAppDetail(a) {
    var aw = awardedPlacesOf(a), req = requestedPlacesOf(a);
    var qty = qtyOf(a), assigned = awardedOf(a) || qty;
    var fee = feeFor(assigned, a.days);
    var feeRows = (fee.lines || []).map(function (l) { return '<dt>' + esc(l[0]) + '</dt><dd>' + esc(l[1]) + '</dd>'; }).join('');
    var design = a.fileName
      ? '<dt>시안 파일</dt><dd>' + esc(a.fileName) + '</dd>'
      : '<dt>시안 파일</dt><dd>시연용 시안(자동 생성)</dd>';
    return '<div class="mp-detail">' +
      '<button class="btn ghost sm mp-back" type="button" data-mpback="1">← 접수 목록으로</button>' +
      '<div class="panel">' +
        '<div class="panel-head"><h3>' + IC.doc + ' 접수 ' + esc(a.id) + '</h3>' + statusBadge(a.status) + eventBadgeHTML(a) + '</div>' +
        myAppCard(a) +
        '<div class="summary" style="margin-top:14px"><dl>' +
          '<dt>접수번호</dt><dd>' + esc(a.id) + '</dd>' +
          '<dt>신청 업체</dt><dd>' + esc(a.company || '—') + '</dd>' +
          '<dt>실제 광고주</dt><dd>' + esc(advOfApp(a).name || '—') + '</dd>' +
          '<dt>현수막 문구</dt><dd>' + esc(a.text || '—') + '</dd>' +
          '<dt>접수 매수</dt><dd>' + qty + '매' + (assigned !== qty ? ' (배정 ' + assigned + '매)' : '') + '</dd>' +
          '<dt>신청일</dt><dd>' + esc(a.appliedAt || '—') + '</dd>' +
          (a.repeatGroupId ? '<dt>반복접수</dt><dd>' + repeatBadgeHTML(a) +
            '<div class="sm" style="margin-top:4px">' + esc(a.repeatStatus === '당첨 자동해제' ? '당첨 확정으로 자동 해제되었습니다 — 다음 주 월요일 게첨 · 후결제로 진행됩니다.'
              : (a.repeatStatus === '사용자 해제' ? '사용자가 반복접수를 해제했습니다.'
              : '미당첨 시 다음 주에 같은 조건으로 자동 재접수됩니다 · 비용은 당첨 확정 후 결제(미당첨 시 0원) · 현수막도 당첨 후 제작')) +
            ' · 그룹 ' + esc(a.repeatGroupId) + '</div></dd>' : '') +
          '<dt>게시 기간</dt><dd>' + esc((a.start || ROUND.periodStart) + ' ~ ' + roundPostEnd(a)) + '</dd>' +
          (a.directInstall
            ? '<dt>설치 방식</dt><dd><b>진행 중 주간 잔여석 — ' + liveInstallLabel(liveInstallKindOf(a)) + '</b><br>' +
              esc(a.directInstallMsg || liveMsgOf(liveInstallKindOf(a))) +
              '<br><b style="color:#b42318">' + esc(liveSealNote(liveInstallKindOf(a))) + '</b></dd>'
            : '') +
          design +
          '<dt>1순위 게시대</dt><dd>' + esc(placeNamesTxt(prioOf(a, 1), 4) || '—') + '</dd>' +
          '<dt>2·3순위</dt><dd>' + esc((a.designatedOnly ? '미적용 (위치지정)' : (placeNamesTxt(prioOf(a, 2), 3) || '미선택') + ' / ' + (placeNamesTxt(prioOf(a, 3), 3) || '미선택'))) + '</dd>' +
          '<dt>배정 게시대</dt><dd>' + esc(aw.length ? awardsTxt(a, 6) : '추첨 전 — 신청 기준') + '</dd>' +
          (a.eventApp ? '<dt>행사 우선접수</dt><dd>' + esc(a.eventName || '행사명 미입력') + ' · ' + esc(a.eventPeriod || '기간 미입력') +
            '<br>' + eventBadgeHTML(a) + ' <span class="sm">' + esc(eventStateOf(a).label) + ' · 찬성 ' + eventStateOf(a).yes + ' / 반려 ' + eventStateOf(a).no +
            ' / 기권 ' + eventStateOf(a).abs + ' (5명 중 3명 이상 찬성 시 확정)</span></dd>' : '') +
          feeRows +
          '<dt>수수료 합계</dt><dd><b>' + won(fee.total) + '</b></dd>' +
        '</dl></div>' +
        photoSectionHTML(a) +
        '<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap">' +
          '<button class="btn sm" data-receipt="' + esc(a.id) + '" type="button">접수증 출력</button>' +
          (['입고대기', '입고완료', '게시중', '선착순확정'].indexOf(a.status) >= 0
            ? '<button class="btn sm primary" data-desig="' + esc(a.id) + '" type="button">게시지정서 출력</button>' : '') +
          '<button class="btn sm ghost" data-zoom="' + esc(a.id) + '" type="button">시안 확대</button>' +
          preDrawCancelBtn(a) +
          (['입고대기', '선착순확정'].indexOf(a.status) >= 0
            ? '<button class="btn sm danger" data-selfcancel="' + esc(a.id) + '" type="button">본인 취소</button>' : '') +
          (a.autoRepeat ? '<button class="btn sm ghost" data-repeatoff="' + esc(a.id) + '" type="button">🔁 반복접수 해제</button>' : '') +
        '</div>' +
      '</div></div>';
  }

  function myAppCard(a) {
    var req = requestedPlacesOf(a);
    var aw = awardedPlacesOf(a);
    var place = placeNamesTxt(req, 2) || '—';
    var end = roundPostEnd(a);
    var extra = '';
    if (a.status === '반려') extra = '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.alert + '<div><b>반려 사유</b> ' + esc(a.reject || '규정 미준수') + ' — 문구 수정 후 다시 접수해 주세요.</div></div>';
    if (a.status === '미입고취소') extra = '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.x + '<div><b>미입고 취소(반려)</b> ' + esc(a.reject || '현수막 실물 미제출') + ' — 해당 매는 차순위 신청자에게 배정되거나 목요일 선착순 접수로 전환되었습니다. <b>차기 1개 주 회차 접수 제한(페널티)</b>이 적용됩니다.</div></div>';
    if (a.status === '미입금취소') extra = '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.x + '<div><b>미입금 취소</b> ' + esc(a.reject || '수수료 입금 기한 경과') + ' — <b>차기 1개 주 회차 접수 제한(페널티)</b>이 적용됩니다.</div></div>';
    if (a.status === '본인취소') extra = '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.x + '<div><b>본인 사유 취소</b> ' + esc(a.reject || '광고주 요청') + ' — <b>차기 1개 주 회차 접수 제한(페널티)</b>이 적용됩니다.</div></div>';
    if (a.status === '접수취소') extra = '<div class="callout info" style="margin-top:10px;margin-bottom:0">' + IC.info + '<div><b>추첨 전 취소</b> — 추첨 확정 전에 취소하셨으므로 <b>페널티가 없습니다</b>. 같은 회차에 다시 접수할 수 있습니다.</div></div>';
    if (a.status === '낙첨') extra = '<div class="callout info" style="margin-top:10px;margin-bottom:0">' + IC.info + '<div>이번 회차 배정에서 제외되었습니다. 잔여 면은 <b>목요일 선착순 접수</b>로 신청할 수 있습니다.</div></div>';
    var ev = eventStateOf(a);
    if (ev.on && ev.status === '심사중') extra += '<div class="callout info" style="margin-top:10px;margin-bottom:0">' + IC.info + '<div><b>행사 심사 중</b> — ' + esc(a.eventName || '행사') + ' (' + esc(a.eventPeriod || '') + ') · 행사승인권한자 <b>5명 중 ' + ev.yes + '명 찬성</b> (3명 이상이면 승인 확정). 반려·기권이 3명 이상이면 일반 추첨으로 전환됩니다.</div></div>';
    if (ev.on && ev.status === '승인') extra += '<div class="callout ok" style="margin-top:10px;margin-bottom:0">' + IC.check + '<div><b>행사 우선 승인</b> — ' + esc(a.eventName || '행사') + ' · 이번 추첨에서 <b>공문 다음 · 일반 접수보다 먼저</b> 배정됩니다. (찬성 ' + ev.yes + '/5)</div></div>';
    if (ev.on && ev.status === '미승인') extra += '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.alert + '<div><b>행사 우선접수 미승인 → 일반 추첨 전환</b> — 찬성이 3명에 미치지 못했습니다(찬성 ' + ev.yes + ' · 반려 ' + ev.no + ' · 기권 ' + ev.abs + '). 신청한 <b>1·2·3순위 그대로</b> 일반 추첨에 참여합니다.</div></div>';
    if (a.status === '입고대기' || a.status === '선착순확정') extra = '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.alert +
      '<div><b>현수막 입고 대기</b> — <b>' + esc(dueOf(a)) + '까지 본인 또는 대리인이</b> 협회 사무국(서산시 덕지천로 1, 2층)에 직접 실물을 입고해 주세요. (<b>택배·광고도매상 입고 금지</b>)' +
      (a.paid ? '' : ' 수수료 <b>' + won(feeFor(awardedOf(a) || qtyOf(a), a.days).total) + '</b>(' + (awardedOf(a) || qtyOf(a)) + '매)도 함께 입금해 주세요.') +
      ' 미입고 시 자동 취소(반려)됩니다.</div></div>';
    if (a.status === '입고완료') extra = '<div class="callout ok" style="margin-top:10px;margin-bottom:0">' + IC.check + '<div><b>입고 완료 · 게시 대기</b> — ' + dfmt(a.start || ROUND.postStart) + ' 현장 게첨 후 게시가 시작됩니다.</div></div>';
    if (a.status === '게시중') extra = a.directInstall
      ? '<div class="callout ok" style="margin-top:10px;margin-bottom:0">' + IC.check + '<div><b>게시 중 (진행 중 주간 잔여석)</b> — ' + esc(a.start) + ' ~ ' + end + ' · 설치·게첨은 접수자(광고사 또는 광고주)가 직접 진행한 건입니다.</div></div>'
      : '<div class="callout ok" style="margin-top:10px;margin-bottom:0">' + IC.check + '<div>게시 중 — ' + esc(a.start) + ' ~ ' + end + ' · 기간이 끝나면 협회가 일괄 철거합니다.</div></div>';
    /* 진행 중 주간 잔여석 — 설치 주체 안내를 접수 내역에도 남긴다 (2026-11-23 지시) */
    if (a.directInstall) extra += '<div class="callout warn" style="margin-top:10px;margin-bottom:0">' + IC.alert +
      '<div><b>설치 안내 (진행 중 주간)</b><br>' + esc(a.directInstallMsg || liveMsgOf(liveInstallKindOf(a))) +
      '<br><b>협회 검인(도장) : 접수 확인 후 협회 검인 도장을 날인해 주세요.</b> 검인 없는 현수막은 게첨으로 인정되지 않습니다.' +
      '<span class="sm" style="display:block;margin-top:4px">수수료 ' + won(FEE.total) + '은 접수 후 입금해 주세요.</span></div></div>';
    return '<div class="app-card">' +
      '<div class="ac-top"><div><b>' + esc(place) + '</b>' +
      '<div class="ac-meta" style="margin-top:5px"><span>' + IC.doc + a.id + '</span><span>' + IC.cal +
      (a.start || ROUND.periodStart) + ' ~ ' + end + '</span><span>' + IC.grid + qtyOf(a) + '매 · ' + esc(rankSummaryTxt(a)) +
      (a.assignedTo ? ' / 배정 ' + awardedOf(a) + '매' : '') + '</span><span>' + IC.grid + (a.days || 7) + '일</span></div></div>' +
      '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">' +
      (a.designatedOnly ? '<span class="badge b-purple"><i></i>위치지정</span>' : '') + statusBadge(a.status) + eventBadgeHTML(a) + repeatBadgeHTML(a) + '</div></div>' +
      '<div style="font-size:12.5px;color:var(--muted)">' + esc(a.text) + '</div>' +
      rankListHTML(a) +
      (aw.length ? '<div class="hint-txt">배정 게시대 — ' + esc(awardsTxt(a, 4)) + '</div>' : '') + extra +
      timelineHTML(a.status) +
      '<div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">' +
      '<button class="btn sm" data-receipt="' + a.id + '" type="button">접수증 보기</button>' +
      (['입고대기', '입고완료', '게시중', '선착순확정'].indexOf(a.status) >= 0
        ? '<button class="btn sm primary" data-desig="' + a.id + '" type="button">게시 지정서 출력</button>' : '') +
      (a.status === '낙첨' ? '<button class="btn sm primary" data-goto="first" type="button">선착순 예약</button>' : '') +
      (a.autoRepeat ? '<button class="btn sm ghost" data-repeatoff="' + a.id + '" type="button">🔁 반복접수 해제</button>' : '') +
      '</div></div>';
  }

  /* 회원별 접수 필터 — 로그인한 회원의 접수만 보여 준다 (비회원은 기존처럼 내 접수 전체) */
  function memberAppFilter(a, m) {
    if (!m) return !!a.mine;
    if (a.memberId && a.memberId === m.id) return true;
    var nm = normName(m.company);
    if (!nm) return false;
    if (normName(a.company) === nm) return true;
    if (normName(advOfApp(a).name) === nm) return true;
    return false;
  }

  /* ── 마이페이지 잠금 — 로그아웃(비회원 인증 전) 상태에서는 개인 접수 내역을 그리지 않는다 ──
     2026-11-23 김재봉 님 지시 "로그아웃 상태인데 마이페이지가 열리면 안되지?" ·
     "회원접수시 마이페이지에서 확인해야지. 비회원접수시 번호인증하면 들어가져야지." */
  function mypageGuestPhone() { return String(smsState().phone || '').replace(/[^0-9]/g, ''); }
  function mypageGuestVerified() { return !!smsState().verified; }
  function mypageLocked() { return !currentMember() && !mypageGuestVerified(); }
  /* 비회원 — 인증한 번호로 접수한 내역만 보여 준다 */
  function guestAppFilter(a, phone) {
    var ph = String(phone || '').replace(/[^0-9]/g, '');
    if (!a) return false;
    var cand = [a.phone, a.advertiserPhone, advOfApp(a).phone];
    if (ph) {
      var hit = false;
      cand.forEach(function (x) { if (!hit && String(x || '').replace(/[^0-9]/g, '') === ph) hit = true; });
      if (hit) return true;
    }
    /* 번호가 비어 있는 시연·이전 데이터는 이 브라우저에서 접수한 것만 */
    if (a.mine && !String(a.phone || '').replace(/[^0-9]/g, '')) return true;
    return false;
  }
  var MYPAGE_LOCK_MSG = '로그인 또는 비회원 휴대폰 인증 후 이용할 수 있습니다';
  function mypageLockPanelHTML() {
    return '<div class="panel"><div class="empty mp-lock">' +
      '<div class="mp-lock-ico" aria-hidden="true">🔒</div>' +
      '<div><b>' + MYPAGE_LOCK_MSG + '</b><br>' +
      '이 화면은 <b>내 접수 내역 · 진행 주간 잔여석 접수 · 입금 안내 · 게첨사진</b>을 보여 줍니다. ' +
      '로그아웃 상태에서는 개인 접수 내용을 표시하지 않습니다.</div>' +
      '<div class="mp-lock-btns">' +
      '<button class="btn primary" type="button" data-login-open="1">로그인 / 회원가입</button>' +
      '<button class="btn" type="button" data-mpverify="1">비회원 휴대폰 인증</button></div></div></div>';
  }
  /* 진입 즉시 로그인/비회원 인증 안내 팝업 (한 번만 자동 · 모달이 떠 있으면 그게 끝나길 기다린다) */
  function mypageLockAsk(tries) {
    tries = tries || 0;
    if (!mypageLocked() || ui.mpAskShown) return false;
    /* 같은 브라우저 세션에서는 한 번만 — 화면을 오갈 때마다 팝업이 반복되지 않게 */
    try { if (sessionStorage.getItem('seosan.mpAsk') === '1') return false; } catch (e) { }
    if ($('#modal') && $('#modal').classList.contains('open')) {
      if (tries >= 40) return false;
      setTimeout(function () { mypageLockAsk(tries + 1); }, 250);
      return false;
    }
    ui.mpAskShown = true;
    try { sessionStorage.setItem('seosan.mpAsk', '1'); } catch (e) { }
    openModal({
      title: '🔒 ' + MYPAGE_LOCK_MSG,
      sub: '마이페이지 — 내 접수 내역 확인',
      body: '<div class="callout info"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7.6v.1"/></svg>' +
        '<div><b>세 가지 중 하나로 들어올 수 있습니다.</b><br>' +
        '① <b>회원 로그인</b> — 가입한 업체·대행사 계정으로 로그인하면 내 접수 내역이 보입니다.<br>' +
        '② <b>회원가입</b> — 처음이라면 가입 즉시 로그인되고 접수 1단계가 자동 작성됩니다.<br>' +
        '③ <b>비회원 휴대폰 인증</b> — 비회원으로 접수했던 휴대폰 번호로 인증하면 <b>그 번호로 접수한 내역</b>이 보입니다.</div></div>',
      foot: '<button class="btn ghost" data-close="1" type="button">닫기</button>' +
        '<button class="btn" data-mpverify="1" type="button">비회원 휴대폰 인증</button>' +
        '<button class="btn" data-guestlogin="1" type="button">로그인</button>' +
        '<button class="btn primary" data-guestsignup="1" type="button">회원가입</button>'
    });
    return true;
  }
  /* 비회원 휴대폰 인증 — 인증을 마치면 잠금이 풀리고 그 번호의 접수 내역이 보인다 */
  function openMypageVerify() {
    var st = smsState();
    openModal({
      title: '비회원 휴대폰 인증',
      sub: '인증한 번호로 접수한 내역을 마이페이지에서 확인합니다',
      body: '<div class="field"><label for="mpvPhone">휴대폰 번호</label>' +
        '<input class="input" id="mpvPhone" inputmode="tel" maxlength="13" placeholder="010-0000-0000" value="' + esc(st.phone || '') + '"></div>' +
        '<div class="field"><label for="mpvCode">인증번호 6자리</label>' +
        '<div style="display:flex;gap:6px"><input class="input" id="mpvCode" inputmode="numeric" maxlength="6" placeholder="인증번호">' +
        '<button class="btn" id="btnMpvSend" type="button" style="white-space:nowrap">인증번호 발송</button></div>' +
        '<div class="hint-txt" id="mpvHint">시연용 — [인증번호 발송]을 누르면 6자리 번호가 발급됩니다. 비회원으로 접수할 때 적은 번호로 인증하면 그 번호의 접수 내역이 보입니다. (시연 예시 번호 010-0000-0000)</div></div>',
      foot: '<button class="btn ghost" data-close="1" type="button">닫기</button>' +
        '<button class="btn primary" id="btnMpvOk" type="button">인증 확인</button>',
      after: function () {
        if ($('#btnMpvSend')) onEl('#btnMpvSend', 'click', function () { mypageVerifySend(); });
        if ($('#btnMpvOk')) onEl('#btnMpvOk', 'click', function () { mypageVerifyOk(); });
        if ($('#mpvCode')) onEl('#mpvCode', 'keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); mypageVerifyOk(); } });
      }
    });
  }
  function mypageVerifySend() {
    var ph = String($('#mpvPhone') ? $('#mpvPhone').value : '').replace(/\s/g, '');
    if (!/^01[016789][- ]?\d{3,4}[- ]?\d{4}$/.test(ph)) {
      toast('휴대폰 번호를 정확히 입력해 주세요. (예: 010-1234-5678)', true);
      return null;
    }
    var code = String(Math.floor(100000 + Math.random() * 900000));
    ui.sms = { sent: true, code: code, phone: ph, verified: false, at: nowStamp() };
    if ($('#mpvHint')) $('#mpvHint').textContent = '인증번호가 발급되었습니다 (시연용) — ' + code + ' 를 인증번호 칸에 넣고 [인증 확인]을 누르세요.';
    toast('인증번호가 발급되었습니다 (시연용) — ' + code);
    return code;
  }
  function mypageVerifyOk() {
    var st = smsState();
    if (!st.sent) { toast('먼저 [인증번호 발송]을 눌러 주세요.', true); return false; }
    var ph = String($('#mpvPhone') ? $('#mpvPhone').value : '').replace(/\s/g, '');
    if (String(ph).replace(/[^0-9]/g, '') !== String(st.phone || '').replace(/[^0-9]/g, '')) {
      toast('연락처가 바뀌었습니다 — 인증번호를 다시 발송해 주세요.', true);
      st.sent = false; st.code = ''; st.verified = false;
      return false;
    }
    var input = String($('#mpvCode') ? $('#mpvCode').value : '').replace(/[^0-9]/g, '');
    if (input.length !== 6) { toast('인증번호 6자리를 입력해 주세요.', true); return false; }
    if (input !== st.code) { toast('인증번호가 맞지 않습니다. 다시 확인해 주세요.', true); return false; }
    st.verified = true;
    audit('회원', '비회원 본인인증 완료(마이페이지) — ' + ph);
    closeModal();
    ui.mpAskShown = true;
    renderMypage();
    toast('휴대폰 인증이 완료되었습니다 — 이 번호로 접수한 내역을 보여 줍니다.');
    return true;
  }
  /* 마이페이지 탭은 로그인·로그아웃·관리자와 무관하게 항상 보인다 (2026-11-23 김재봉 님 지시) */
  function ensureMypageTabVisible() {
    var links = $$('nav.site-nav a[href="mypage.html"], #mobileTabbar a[href="mypage.html"]');
    links.forEach(function (a) {
      a.classList.remove('hidden');
      a.removeAttribute('aria-hidden');
      a.removeAttribute('hidden');
      if (a.style && a.style.display === 'none') a.style.display = '';
    });
    return links.length;
  }

  /* 마이페이지 — 접기/펼치기 · 검색 (2026-11-23 김재봉 님 지시 "접기로 시작해서 펼처보게 해주고 / 지난회차가 맨 위로 / 검색키 너어주고") */
  function mpQuery() { return String(ui.mpq || '').trim().toLowerCase(); }
  function mpMatch(a) {
    var q = mpQuery();
    if (!q) return true;
    var places = awardedPlacesOf(a).map(function (x) { var p = boardById(x.pid); return p ? p.name : ''; }).join(' ');
    var prio = (a.priority1 || []).map(function (id) { var p = boardById(id); return p ? p.name : ''; }).join(' ');
    var t = [a.id, a.company, (advOfApp(a) || {}).name, a.text, awardsTxt(a, 4), places, prio].join(' ').toLowerCase();
    return t.indexOf(q) >= 0;
  }
  function mpSectionHTML(key, title, sub, list, extra, openDefault) {
    var q = mpQuery();
    var shown = (list || []).filter(mpMatch);
    if (q && !shown.length) return '';
    var open = q ? true : (ui.mpOpen[key] === undefined ? !!openDefault : !!ui.mpOpen[key]);
    return '<div class="panel mp-sec' + (open ? ' open' : '') + '" data-seckey="' + key + '">' +
      '<button class="mp-sec-head" type="button" data-mptoggle="' + key + '" aria-expanded="' + (open ? 'true' : 'false') + '">' +
      '<span class="mp-sec-t">' + title + '</span><span class="sub">' + esc(sub) + '</span>' +
      '<span class="mp-sec-x">' + (open ? '▾ 접기' : '📂 펼쳐보기') + '</span></button>' +
      (open ? ((extra || '') + (shown.length ? '<div class="mp-list">' + shown.map(myAppRow).join('') + '</div>'
        : '<div class="empty">' + IC.empty + '<div>해당하는 접수 내역이 없습니다.</div></div>')) : '') +
      '</div>';
  }
  function renderMypage() {
    if (!has('mpBody')) return;
    var m = currentMember();
    if (PAGE === 'mypage-detail') return;      /* 상세 페이지는 renderMypageDetail 이 그린다 */
    if (mypageLocked()) {
      $('#mpHead').innerHTML =
        '<div class="avatar">🔒</div><div class="who"><b>로그인이 필요합니다</b><span>' + MYPAGE_LOCK_MSG + '</span></div>' +
        '<div class="spacer"></div><span class="badge b-gray"><i></i>잠금</span>' +
        '<button class="btn sm primary" type="button" data-login-open="1">로그인 / 회원가입</button>' +
        '<button class="btn sm" type="button" data-mpverify="1">비회원 인증</button>';
      $('#mpBody').innerHTML = mypageLockPanelHTML();
      return;
    }
    var gPhone = m ? '' : mypageGuestPhone();
    var company = m ? m.company : ('비회원 인증 ' + (gPhone.length > 7 ? gPhone.slice(0, 3) + '-' + gPhone.slice(3, 7) + '-' + gPhone.slice(7) : gPhone));
    $('#mpHead').innerHTML =
      '<div class="avatar">' + esc(String(company).charAt(0)) + '</div>' +
      '<div class="who"><b>' + esc(company) + '</b><span>' +
        (m ? esc(memberTypeLabel(m) + ' · ' + m.owner + (m.phone ? ' · ' + m.phone : ''))
           : '휴대폰 인증 완료 — 이 번호로 접수한 비회원 내역만 표시됩니다.') +
      '</span></div>' +
      '<div class="spacer"></div>' +
      '<span class="badge ' + (m ? (m.type === 'agency' ? 'b-purple' : 'b-blue') : 'b-gray') + '"><i></i>' +
        esc(m ? memberTypeLabel(m) : '비회원 인증') + '</span>' +
      (m
        ? '<button class="btn sm ghost" type="button" data-logout="1">로그아웃</button>'
        : '<button class="btn sm ghost" type="button" data-mpverify="1">번호 다시 인증</button>' +
          '<button class="btn sm" type="button" data-login-open="1">로그인 / 회원가입</button>') +
      '<button class="btn sm primary" data-goto="apply" type="button">새 접수하기</button>';

    var mine = db.apps.filter(function (a) { return m ? memberAppFilter(a, m) : guestAppFilter(a, gPhone); });
    /* 최신 접수 순(내림차순) — 같은 시각이면 접수번호 큰 것 먼저 */
    mine.sort(function (a, b) {
      var x = String(a.appliedAt || ''), y = String(b.appliedAt || '');
      if (x !== y) return x < y ? 1 : -1;
      return String(b.id || '') < String(a.id || '') ? -1 : 1;
    });
    var curWk = currentPostingWeek();
    var liveWk = weekStartOf(CUR.start);
    var liveNow = mine.filter(function (a) { return weekStartOf(a.start || ROUND.postStart) === liveWk; });
    var cur = mine.filter(function (a) { return weekStartOf(a.start || ROUND.postStart) === curWk; });
    var upcoming = mine.filter(function (a) { return weekStartOf(a.start || ROUND.postStart) > curWk; });
    var past = mine.filter(function (a) { var w = weekStartOf(a.start || ROUND.postStart); return w < curWk && w !== liveWk; });
    upcoming.sort(function (a, b) { return String(a.start) < String(b.start) ? -1 : 1; });

    /* 목록 한 건을 누르면 mypage-detail.html?id=... 로 이동한다 (별도 페이지) */

    var html = '';
    if (m) {
      html += '<div class="callout ok" style="margin-bottom:12px">' + IC.check +
        '<div><b>' + esc(m.company) + '</b> (' + esc(memberTypeLabel(m)) + ') 회원으로 로그인했습니다 — 이 화면에는 <b>내 접수 ' + mine.length + '건</b>만 표시됩니다.</div></div>';
    } else {
      html += '<div class="callout ok" style="margin-bottom:12px">' + IC.check +
        '<div><b>' + esc(company) + '</b> 번호 인증으로 들어왔습니다 — <b>인증한 번호로 접수한 비회원 내역 ' + mine.length +
        '건</b>만 표시됩니다. 다른 번호로 접수했다면 [번호 다시 인증]을 눌러 주세요.</div></div>';
    }
    /* 🔍 실시간 검색 — 접수번호·실제 광고주·문구·게시대 (2026-11-23 김재봉 님 지시) */
    html += '<div class="search search-lg mp-search" style="margin:0 0 12px">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l4.5 4.5"/></svg>' +
      '<input type="search" id="mpSearch" class="ko-ime" lang="ko" placeholder="접수번호 · 실제 광고주 · 문구 · 게시대 검색" aria-label="내 접수 검색" value="' + esc(String(ui.mpq || '')) + '">' +
      '</div>';
    html += '<div class="callout info mp-foldhint" style="margin-bottom:12px"><div>💡 <b>모든 회차 목록이 기본적으로 접혀 있습니다</b> — 보고 싶은 회차 제목을 누르면 펼쳐집니다. 검색어를 넣으면 일치 건이 자동으로 펼쳐집니다.</div></div>';
    /* 이번 주 게첨·진행 주간 → 이번 회차 → 사전 접수 → 지난 회차 (모두 기본 접힘 · 접기 우선) */
    html += mpSectionHTML('live', '🔥 이번 주 게첨 · 진행 중 주간(' + dstr(liveWk) + ' ~ ' + dstr(CUR.end) + ') 잔여석 접수', liveNow.length + '건', liveNow,
      '<div class="callout warn" style="margin:2px 0 12px">' + IC.alert + '<div>이 주간은 협회 일괄 게첨이 끝났습니다 — <b>광고대행사는 직접 현장에 설치(게첨)</b>, <b>일반인은 규정상 직접 설치가 금지되어 반드시 옥외광고업 등록 광고사에 의뢰</b>해야 합니다.</div></div>', false);
    html += mpSectionHTML('cur', IC.doc + ' ' + esc(weekRangeTxt(curWk)) + ' 게첨 주 접수', cur.length + '건 · 이번 회차', cur, '', false);
    html += mpSectionHTML('up', IC.cal + ' 사전 접수 · 게첨 예정', upcoming.length + '건', upcoming, '', false);
    html += mpSectionHTML('past', IC.cal + ' 지난 회차 · 게시 중·종료', past.length + '건', past, '', false);

    var needPay = mine.filter(function (a) { return (a.status === '입고대기' || a.status === '선착순확정') && !a.paid; });
    if (needPay.length) {
      var needTotal = 0;
      needPay.forEach(function (a) { needTotal += feeFor(awardedOf(a) || qtyOf(a), a.days).total; });
      html += '<div class="panel"><div class="panel-head"><h3>' + IC.money + ' 입금 안내 (가상계좌)</h3></div>' +
        '<div class="bank"><h4>' + IC.money + ' 농협 301-0123-4567-89</h4>' +
        '<div class="acct"><small>예금주</small>(사)충청남도옥외광고협회 서산시지부</div>' +
        '<p>입금자명은 반드시 <b style="color:#fff">실제 광고주명</b>으로 입력해 주세요. 대상 ' + needPay.length + '건 · <b style="color:#fff">배정 매수 × 1매 단가(' + won(FEE.total) + ')</b> · 합계 <b style="color:#fff">' + won(needTotal) + '</b><br>입금과 함께 <b style="color:#fff">현수막 실물을 ' + dfmt(ROUND.deliverBy) + ' ' + ROUND.deliverTime + '까지</b> 협회로 입고해 주세요. 미입고 시 자동 취소(반려)됩니다.</p></div></div>';
    }
    $('#mpBody').innerHTML = html;
  }

  /* ---------------------------------------------------------------
     9-1. 회원 로그인 · 회원가입 · 접수 양식 자동 작성
     ---------------------------------------------------------------
     · 시연용 간편 로그인 프리셋 3개 (원클릭) + 아이디·비밀번호 로그인 + 간편 회원가입
     · 로그인하면 1단계 입력칸(구분·업체명·대표자·연락처·사업자번호·이메일·옥외광고업 등록번호)이 자동 작성됩니다.
     · 로그아웃하면 자동 작성한 값이 지워지고, 비회원 직접 입력도 그대로 쓸 수 있습니다. */
  var TYPE_LABEL = { direct: '일반광고주', agency: '광고대행사', assoc: '협회회원', staff: '협회직원' };
  function memberTypeOf(m) {
    if (!m) return 'direct';
    if (m.type === 'staff' || m.isStaff) return 'staff';
    if (m.type === 'assoc' || m.assocMember) return 'assoc';
    if (m.type === 'agency') return 'agency';
    return 'direct';
  }
  /* 첫 방문(저장 데이터 없음)에는 db가 아직 만들어지기 전에 시연 데이터 생성 단계에서 불릴 수 있다.
     — 그때는 기본 회원 명단(SEED_MEMBERS)을 돌려줘야 시연 데이터가 멈추지 않는다 (2026-11-28 수정) */
  function memberList() {
    if (!db) return SEED_MEMBERS || [];
    if (!db.members) db.members = [];
    return db.members;
  }
  function agencyAppCount(memberId) {
    if (!memberId) return 0;
    return db.apps.filter(function (a) { return a.memberId === memberId; }).length;
  }
  function memberById(id) {
    var out = null;
    memberList().forEach(function (m) { if (!out && m.id === id) out = m; });
    return out;
  }
  function findMemberByLogin(loginId) {
    var key = String(loginId == null ? '' : loginId).trim().toLowerCase();
    if (!key) return null;
    var out = null;
    memberList().forEach(function (m) { if (!out && String(m.loginId || '').toLowerCase() === key) out = m; });
    return out;
  }
  function currentMember() { return (db && db.session) ? memberById(db.session) : null; }
  function memberTypeLabel(m) { return TYPE_LABEL[memberTypeOf(m)] || '일반광고주'; }
  /* 접수 건의 회원 — 접수 때 저장한 memberId, 없으면 같은 업체명 회원 */
  function memberOfApp(a) {
    if (!a) return null;
    var m = a.memberId ? memberById(a.memberId) : null;
    if (m) return m;
    var out = null;
    memberList().forEach(function (x) {
      if (!out && x.company && a.company && String(x.company) === String(a.company)) out = x;
    });
    return out;
  }
  /* 헤더 로그인 버튼 ↔ 회원 정보 칩 */
  function renderAuth() {
    var m = currentMember();
    var b = $('#btnLogin'), u = $('#authUser');
    if (b) b.classList.toggle('hidden', !!m);
    if (u) u.classList.toggle('hidden', !m);
    if (m) {
      if ($('#authName')) $('#authName').textContent = m.company;
      if ($('#authSub')) $('#authSub').textContent = memberTypeLabel(m) + ' · ' + m.owner;
    } else {
      /* 로그아웃 — 이전 회원 이름이 화면에 남지 않게 지운다 */
      if ($('#authName')) $('#authName').textContent = '';
      if ($('#authSub')) $('#authSub').textContent = '';
    }
    renderMemberBanner();
  }
  /* 1단계 상단 자동 작성 안내 */
  function renderMemberBanner() {
    var m = currentMember(), el = $('#memberBanner');
    if (!el) return;
    el.classList.toggle('hidden', !m);
    if (!m) return;
    if ($('#memberBannerName')) $('#memberBannerName').textContent = m.company + ' (' + memberTypeLabel(m) + ') 회원';
    if ($('#memberBannerNote')) $('#memberBannerNote').textContent = m.type === 'agency'
      ? '대행사 정보로 작성했습니다 — 실제 광고주(광고를 의뢰한 사업자)는 직접 입력해 주세요.'
      : '로그아웃하면 자동 작성이 초기화됩니다.';
  }

  /* 1단계 양식 자동 작성 — force=false 면 비어 있는 칸만 채운다 */
  function applyAutofill(force) {
    var m = currentMember();
    if (!m) return false;
    function set(sel, val) {
      var el = $(sel);
      if (!el) return;
      if (!force && String(el.value == null ? '' : el.value).trim()) return;
      el.value = val == null ? '' : String(val);
    }
    /* 회원 구분(일반업체/광고대행사)에 맞춰 신청 구분을 자동 선택
       · 로그인(force) 때는 항상, 그 밖에는 사용자가 직접 바꾸기 전까지만 회원 구분을 따른다 */
    if (force || !ui.appTypeTouched) ui.appType = (m.type === 'agency') ? 'agency' : 'direct';
    set('#applyCompany', m.company);
    set('#applyOwner', m.owner);
    set('#applyPhone', m.phone);
    set('#applyBiz', m.biz);
    set('#applyEmail', m.email);
    /* 옥외광고업 등록번호·등록증 사본은 자동 작성하지 않습니다
       · 광고대행사만 '본인 대행사' 등록번호를 채웁니다.
       · 일반업체는 매번 의뢰한 현수막 출력업체 번호를 직접 입력하고 등록증 사본을 첨부해야 합니다. */
    if ((ui.appType || 'direct') === 'agency') {
      set('#applyOade', m.oade);
    } else if (force && $('#applyOade')) {
      $('#applyOade').value = '';
    }
    if ((ui.appType || 'direct') === 'agency') {
      /* 대행 신청 — 실제 광고주는 대행사가 아니라 광고를 의뢰한 사업자이므로 비워 둔다 */
      if (force) {
        if ($('#applyAdvertiser')) $('#applyAdvertiser').value = '';
        if ($('#applyAdvBiz')) $('#applyAdvBiz').value = '';
        if ($('#applyAdvPhone')) $('#applyAdvPhone').value = '';
      }
    } else {
      set('#applyAdvertiser', m.company);
      set('#applyAdvBiz', m.biz);
      set('#applyAdvPhone', m.phone);
    }
    /* 등록증 사본 — 광고대행사는 가입 때 1회 제출로 갈음하고 접수 화면에 칸이 없습니다.
       일반업체·비회원은 접수마다 광고사(출력업체) 등록증 사본을 첨부해야 하므로 비워 둡니다. */
    if (force) {
      ui.licName = ''; ui.licData = ''; ui.licMime = ''; ui.licFromMember = false;
      ui.licNo = ''; ui.licNoSrc = ''; ui.licNoFail = false;
      if ($('#applyLic')) { try { $('#applyLic').value = ''; } catch (e) { } }
      renderLicName();
    }
    syncAppType();
    renderMemberBanner();
    return true;
  }

  /* 로그인 — 세션 저장 후 1단계 자동 작성 · 마이페이지 필터 */
  function loginMember(m, opts) {
    if (!m) return null;
    db.session = m.id;
    ui.appTypeTouched = false;
    /* 협회 직책자 회원(지부장·수석·사무국장·사무실무원·감사)은 로그인하면 그 직책 권한으로 바로 들어간다 */
    if (m.roleKey) {
      try {
        ui.adminRole = officerRoleMeta(m.roleKey).k;
        localStorage.setItem(OFFICER_KEY, ui.adminRole);
      } catch (e) { }
    }
    audit('회원', m.company + ' 로그인 (' + memberTypeLabel(m) + ' · ' + m.loginId + ')');
    save();
    closeModal();
    clearLogoutLock();
    renderAuth();
    applyAutofill(true);
    if (ui.step !== 1) setStep(ui.step); else renderApply();
    /* 광고대행사로 로그인하면 미배정 선착순 1단계의 등록증 칸도 즉시 사라져야 한다 (2026-11-23 김재봉 님 지시) */
    if (PAGE === 'first' || PAGE === 'remain') { try { renderFirst(); } catch (e) { } }
    renderMypage();
    if (!(opts && opts.silent)) toast(m.company + ' (' + memberTypeLabel(m) + ') 님으로 로그인했습니다 — 1단계 입력을 회원 정보로 자동 작성했습니다.');
    makerBlockNotice();
    /* 로그인 직후 — 내가 결재·심사할 대기 건이 있으면 어느 화면이든 바로 팝업 (2026-11-23 김재봉 님 제보) */
    try {
      if (m.roleKey || ui.roleLoginPriority) { refreshRoleDependentViews(); applySubtabs('admin'); }
      ui.approvalPopupShownFor = '';
      try { sessionStorage.removeItem('seosan.approvalPopAck'); } catch (e) { }
      setTimeout(maybeShowApprovalPopup, 400);
    } catch (e) { }
    /* 로그인 팝업에서 로그인한 경우 — 대기 중이던 진행을 그대로 이어서 */
    var pend = ui.pendingAdvance;
    ui.pendingAdvance = '';
    if (pend === 'next') { try { nextStep(true); } catch (e) { } }
    else if (pend === 'fcnext') { try { fcNextStep(); } catch (e) { } }
    else if (pend && pend.indexOf('first:') === 0) { try { bookFirst(pend.slice(6)); } catch (e) { } }
    else if (pend && pend.indexOf('live:') === 0) { try { bookLive(pend.slice(5)); } catch (e) { } }
    return m;
  }
  function submitLogin(idArg, pwArg) {
    var idEl = $('#loginId'), pwEl = $('#loginPw');
    var id = (idArg != null) ? String(idArg).trim() : (idEl ? String(idEl.value || '').trim() : '');
    var pw = (pwArg != null) ? String(pwArg) : (pwEl ? String(pwEl.value || '') : '');
    var m = findMemberByLogin(id);
    if (!m || String(m.pw) !== pw) {
      toast('아이디 또는 비밀번호가 맞지 않습니다. 간편 로그인으로도 체험할 수 있습니다.', true);
      return false;
    }
    if (m.approvalStatus === 'pending') {
      toast('마스터 승인 대기 중인 계정입니다. 승인 완료 후 로그인할 수 있습니다.', true);
      return false;
    }
    if (m.approvalStatus === 'rejected') {
      toast('가입 신청이 반려된 계정입니다. 협회 사무국으로 문의해 주세요.', true);
      return false;
    }
    loginMember(m);
    return true;
  }
  function loginPreset(key) {
    var m = memberById(key) || findMemberByLogin(key);
    if (!m) { toast('시연용 회원을 찾을 수 없습니다.', true); return null; }
    return loginMember(m);
  }
  /* 비회원(미로그인) — 1단계 입력칸을 완전히 비운다
     · 김재봉 님 지시: "비회원 로그인시에는 캐쉬메모리 삭제하고 모든칸은 공백으로"
     · 로그아웃 · 비회원으로 계속 · 처음 미로그인 상태에서 호출 — 이전 입력·자동작성·브라우저 캐시 잔존값을 모두 지운다 */
  var APPLY_FIELD_SELS = ['#applyCompany', '#applyOwner', '#applyPhone', '#applyBiz', '#applyEmail',
    '#applyOade', '#applyAdvertiser', '#applyAdvBiz', '#applyAdvPhone', '#applyText'];
  function clearApplyFields() {
    APPLY_FIELD_SELS.forEach(function (sel) {
      var el = $(sel);
      if (el) el.value = '';
    });
    ['#chkRule', '#chkDup'].forEach(function (sel) {
      var el = $(sel);
      if (el) el.checked = false;
    });
    ['#applyLic', '#applyFile'].forEach(function (sel) {
      var el = $(sel);
      if (!el) return;
      try { el.value = ''; } catch (e) { }
    });
    ui.file = null; ui.filePreview = null;
    ui.sms = { sent: false, code: '', phone: '', verified: false, at: '' };
    if ($('#smsCode')) $('#smsCode').value = '';
    ui.licName = ''; ui.licData = ''; ui.licMime = ''; ui.licFromMember = false;
    ui.appType = 'direct'; ui.appTypeTouched = false;
    if ($('#textCount')) $('#textCount').textContent = '0';
    if ($('#urgentHint')) $('#urgentHint').classList.add('hidden');
    try { renderFilePreview(); } catch (e) { }
    try { renderLicName(); } catch (e) { }
    $$('#step1 .field.invalid').forEach(function (f) { f.classList.remove('invalid'); });
    var hint = $('#advTypeHint');
    if (hint) hint.textContent = '직접 신청 — 실제 광고주는 신청 업체와 같게 자동 입력됩니다. 필요하면 수정할 수 있습니다.';
    try { syncAppType(); } catch (e) { }   /* 로그아웃했으니 신청 구분 잠금 해제 */
    return true;
  }

  /* 로그아웃 — 자동 작성한 회원 정보를 지우고 비회원 직접 입력으로 돌아간다 */
  /* 로그아웃 — 세션만 지우지 않고 **지금 보고 있는 화면의 내용을 즉시 비운다**
     (2026-11-23 김재봉 님 지시 "로그아웃하면 현재보던창 내용 비활성화 해주고")
     · 접수 화면(apply/first): 입력·선택·첨부·단계 전부 초기화
     · 마이페이지·상세·관리자 화면: 내용을 잠그고 로그인 유도 안내로 바꾼다 */
  function clearLogoutLock() {
    var old = document.getElementById('logoutLock');
    if (old && old.parentNode) old.parentNode.removeChild(old);
    $$('.view.logout-locked').forEach(function (v) { v.classList.remove('logout-locked'); });
  }
  function logoutLockScreen() {
    var main = document.querySelector('main.main') || document.querySelector('main');
    if (!main) return;
    clearLogoutLock();
    var block = (PAGE === 'mypage' || PAGE === 'mypage-detail' || isAdminPage());
    var view = document.querySelector('section.view');
    if (block && view) view.classList.add('logout-locked');
    var box = document.createElement('div');
    box.id = 'logoutLock';
    box.className = 'callout warn logout-lock';
    box.innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8.5 11V8a3.5 3.5 0 0 1 7 0v3"/></svg>' +
      '<div><b>로그아웃되었습니다 — 이 화면의 내용을 비웠습니다.</b> ' +
      (block ? '내 접수·권한 화면은 로그인해야 볼 수 있습니다.' : '이전에 입력한 접수 내용은 모두 지웠습니다.') +
      '<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">' +
      '<button class="btn sm primary" type="button" data-login-open="1">로그인 / 회원가입</button>' +
      (block ? '' : '<button class="btn sm ghost" type="button" data-guestnotice="1">비회원으로 계속 접수</button>') +
      '</div></div>';
    main.insertBefore(box, main.firstChild);
    if (block) window.scrollTo(0, 0);
  }
  function logoutMember(opts) {
    var m = currentMember();
    db.session = null;
    ui.appTypeTouched = false;
    ui.appType = 'direct';
    audit('회원', (m ? m.company : '비회원') + ' 로그아웃');
    save();
    /* 접수 화면 — 단계·순위·슬롯·첨부·입력값 전부 초기화 */
    if (has('applyForm')) { try { resetApply(); } catch (e) { } }
    clearApplyFields();
    /* 미배정 선착순(first.html) 4단계 입력·선택·첨부도 비운다 */
    if (has('fcForm')) { try { fcReset(); } catch (e) { } }
    ui.fcLic = null; ui.pendingAdvance = ''; ui.liveKind = ''; ui.liveLic = null;
    if (ui.sms) ui.sms = { sent: false, code: '', phone: '', verified: false, at: '' };
    ui.guestAck = false;          /* 로그아웃하면 다시 물어본다 */
    ui.mpAskShown = false;        /* 마이페이지 잠금 안내도 다시 띄운다 */
    ui.guestPromptOpen = false;
    closeModal();
    renderAuth();
    if (ui.roleLoginPriority) { try { refreshRoleDependentViews(); applySubtabs('admin'); } catch (e) { } }
    if (PAGE === 'apply' || PAGE === 'apply-event') { try { renderApply(); } catch (e) { } }
    if (PAGE === 'first' || PAGE === 'remain') { try { renderFirst(); } catch (e) { } }
    try { renderMypage(); } catch (e) { }
    if (PAGE === 'mypage-detail' && $('#mpBody')) {
      /* 상세 화면 — 로그아웃하면 이전 접수 상세 내용을 지우고 로그인 안내로 바꾼다 */
      $('#mpBody').innerHTML = '<div class="panel"><div class="empty">' +
        '<div><b>로그인이 필요합니다.</b><br>로그아웃되어 접수 상세 내용을 지웠습니다. 로그인하면 내 접수 내역을 다시 볼 수 있습니다.</div>' +
        '<div style="margin-top:12px;display:flex;gap:6px;justify-content:center;flex-wrap:wrap">' +
        '<button class="btn sm primary" type="button" data-login-open="1">로그인 / 회원가입</button>' +
        '<a class="btn sm ghost" href="mypage.html">마이페이지로</a></div></div></div>';
    }
    if (isAdminPage()) { try { renderAdmin(); } catch (e) { } }
    logoutLockScreen();
    if (!(opts && opts.silent)) toast('로그아웃했습니다 — 화면의 회원 정보·입력 내용을 지웠습니다.');
    return true;
  }
  /* 비회원으로 계속 — 로그인하지 않고 접수한다 (이전 입력·캐시 삭제 후 1단계 공백) */
  function guestContinue() {
    if (currentMember()) logoutMember({ silent: true });
    clearApplyFields();
    ui.guestAck = true;
    syncAppType();
    closeModal();
    clearLogoutLock();
    renderAuth();
    toast('비회원으로 접수합니다 — 1단계 입력칸을 모두 비웠습니다. 필요한 정보를 직접 입력해 주세요.');
    return true;
  }
  /* 간편 회원가입 — 가입 즉시 로그인 */
  function nextMemberId() {
    var n = 1001;
    memberList().forEach(function (m) {
      var x = Number(String(m.id || '').replace(/[^0-9]/g, ''));
      if (x >= n) n = x + 1;
    });
    return 'M-' + n;
  }
  function signupValues() {
    function v(sel) { var el = $(sel); return el ? String(el.value == null ? '' : el.value).trim() : ''; }
    var typeEl = $('#suType');
    return {
      type: (typeEl && typeEl.value === 'agency') ? 'agency' : 'direct',
      company: v('#suCompany'), owner: v('#suOwner'), phone: v('#suPhone'),
      biz: v('#suBiz'), email: v('#suEmail'), oade: v('#suOade'),
      loginId: v('#suId'), pw: ($('#suPw') ? String($('#suPw').value || '') : ''),
      license: ui.suLicName || '', licenseData: ui.suLicData || '', licenseMime: ui.suLicMime || '',
      licenseNo: ui.suLicNo || ''
    };
  }
  function submitSignup(vals) {
    var v = vals || signupValues();
    v = {
      type: v.type === 'agency' ? 'agency' : 'direct',
      company: String(v.company || '').trim(), owner: String(v.owner || '').trim(),
      phone: String(v.phone || '').trim(), biz: String(v.biz || '').trim(),
      email: String(v.email || '').trim(), oade: String(v.oade || '').trim(),
      loginId: String(v.loginId || '').trim(), pw: String(v.pw || ''),
      license: String(v.license || '').trim(), licenseData: String(v.licenseData || ''), licenseMime: String(v.licenseMime || ''),
      licenseNo: String(v.licenseNo || '').trim()
    };
    if (!v.company) { toast('업체·단체명을 입력해 주세요.', true); return false; }
    if (!v.owner) { toast('대표자·담당자 성명을 입력해 주세요.', true); return false; }
    if (!/^01[016789][- ]?\d{3,4}[- ]?\d{4}$/.test(v.phone.replace(/\s/g, ''))) { toast('연락처를 정확히 입력해 주세요. (예: 010-1234-5678)', true); return false; }
    if (v.biz && normDigits(v.biz).length !== 10) { toast('사업자등록번호는 숫자 10자리로 입력해 주세요.', true); return false; }
    if (v.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.email)) { toast('이메일 형식을 확인해 주세요.', true); return false; }
    if (v.type === 'agency' && !v.license) { toast('옥외광고대행사는 가입할 때 옥외광고업 등록증 사본을 첨부해야 합니다.', true); return false; }
    if (v.loginId.length < 4) { toast('아이디는 4자 이상 입력해 주세요. (영문·숫자)', true); return false; }
    if (v.pw.length < 4) { toast('비밀번호는 4자 이상 입력해 주세요.', true); return false; }
    if (findMemberByLogin(v.loginId)) { toast('이미 사용 중인 아이디입니다. 다른 아이디를 입력해 주세요.', true); return false; }
    var m = {
      id: nextMemberId(), loginId: v.loginId, pw: v.pw, type: v.type,
      company: v.company, owner: v.owner, phone: v.phone,
      biz: v.biz, email: v.email, oade: v.oade, joinedAt: nowStamp(),
      approvalStatus: 'pending',
      licenseNo: v.licenseNo || '',
      licenseFile: (v.type === 'agency' && v.license) ? { name: v.license, data: v.licenseData || '', mime: v.licenseMime || '' } : null
    };
    memberList().push(m);
    ui.suLicName = ''; ui.suLicData = ''; ui.suLicMime = ''; ui.suLicNo = ''; ui.suLicNoSrc = '';
    audit('회원', '신규 회원가입 신청 — ' + m.company + ' (' + m.loginId + ') · 마스터 승인 대기');
    save();
    renderMemberPendingPanel();
    toast(m.company + ' 회원가입 신청이 접수되었습니다. 마스터 승인 후 로그인할 수 있습니다.');
    return m;
  }

  /* 로그인 · 회원가입 모달 */
